# builder/gen_ch23_p1.py
# -*- coding: utf-8 -*-

exercises = [{'num': 1, 'title': 'Паттерн Fan-Out / Fan-In: параллельная обработка и слияние результатов', 'task': 'Fan-out/Fan-in: генератор чисел, несколько горутин умножают числа на 2, затем объединяют результаты в один канал.', 'theory': 'Паттерн Fan-Out/Fan-In — фундаментальный архитектурный паттерн конкурентности в Go. Fan-Out (Разветвление) распределяет задачи из одного канала между $N$ параллельными горутинами для параллельного выполнения на всех ядрах CPU. Fan-In (Слияние) мультиплексирует выходные каналы всех воркеров в единый результирующий поток с помощью `sync.WaitGroup`.', 'step_by_step': '1. Создадим генератор `generator(nums ...int) <-chan int`.\n2. Запустим несколько параллельных воркеров (Fan-Out): `worker(in <-chan int) <-chan int`.\n3. Реализуем функцию слияния (Fan-In): `merge(cs ...<-chan int) <-chan int`.\n4. В `main` прочитаем результаты из общего канала.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\n// Генератор входных данных\nfunc generator(nums ...int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor _, n := range nums {\n\t\t\tout <- n\n\t\t}\n\t}()\n\treturn out\n}\n\n// Воркер (Fan-Out этап)\nfunc multiplier(in <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tout <- n * 2\n\t\t}\n\t}()\n\treturn out\n}\n\n// Слияние N каналов в один (Fan-In этап)\nfunc merge(cs ...<-chan int) <-chan int {\n\tout := make(chan int)\n\tvar wg sync.WaitGroup\n\n\toutput := func(c <-chan int) {\n\t\tdefer wg.Done()\n\t\tfor n := range c {\n\t\t\tout <- n\n\t\t}\n\t}\n\n\twg.Add(len(cs))\n\tfor _, c := range cs {\n\t\tgo output(c)\n\t}\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(out)\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tin := generator(1, 2, 3, 4, 5, 6)\n\n\t// Fan-Out: 2 параллельных воркера\n\tw1 := multiplier(in)\n\tw2 := multiplier(in)\n\n\t// Fan-In: слияние результатов в один канал\n\tfor res := range merge(w1, w2) {\n\t\tfmt.Printf("Получен результат умножения: %d\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получен результат умножения: 2\n# Получен результат умножения: 4\n# Получен результат умножения: 6\n# Получен результат умножения: 8\n# Получен результат умножения: 10\n# Получен результат умножения: 12'}], 'under_the_hood': 'Несколько горутин `multiplier` конкурируют за получение элементов из одного входного канала `in`. Рантайм Go гарантирует, что каждый элемент канала достанется ровно одной горутине без дублирования.', 'pitfalls': 'Закрытие результирующего канала `out` до завершения всех горутин `output` приведет к фатальной панике `panic: send on closed channel`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в паттерне Fan-In закрытие результирующего канала выносят в отдельную горутину go func() { wg.Wait(); close(out) }?»\n**Ответ:** Потому что функция `merge` обязана сразу вернуть канал `<-chan int` вызывающему коду без блокировки, а закрытие канала должно произойти строго асинхронно после вычитки всех входных каналов.'}, {'num': 2, 'title': 'Паттерн Pipeline (Конвейер): трехстадийная потоковая обработка данных', 'task': '**Pipeline (Конвейер)**: Создайте цепочку из трех горутин: первая генерирует числа, вторая возводит их в квадрат, третья фильтрует четные. Соедините их каналами.', 'theory': 'Паттерн Pipeline разбивает сложную вычислительную задачу на цепочку изолированных стадий. Каждая стадия принимает канал `<-chan T` и возвращает новый канал `<-chan T`, обеспечивая высокую степень композируемости и линейную масштабируемость.', 'step_by_step': '1. Стадия 1 `gen`: генерация чисел 1..10.\n2. Стадия 2 `sq`: возведение входных чисел в квадрат.\n3. Стадия 3 `filterEven`: пропуск только четных чисел.\n4. В `main` соединим стадии в цепочку `filterEven(sq(gen(...)))`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\n// 1. Стадия генерации\nfunc gen(nums ...int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor _, n := range nums {\n\t\t\tout <- n\n\t\t}\n\t}()\n\treturn out\n}\n\n// 2. Стадия возведения в квадрат\nfunc sq(in <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tout <- n * n\n\t\t}\n\t}()\n\treturn out\n}\n\n// 3. Стадия фильтрации четных чисел\nfunc filterEven(in <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tif n%2 == 0 {\n\t\t\t\tout <- n\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc main() {\n\tpipeline := filterEven(sq(gen(1, 2, 3, 4, 5, 6, 7, 8)))\n\n\tfmt.Println("Результаты работы 3-стадийного конвейера:")\n\tfor val := range pipeline {\n\t\tfmt.Printf(" -> Четный квадрат: %d\\n", val)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результаты работы 3-стадийного конвейера:\n#  -> Четный квадрат: 4\n#  -> Четный квадрат: 16\n#  -> Четный квадрат: 36\n#  -> Четный квадрат: 64'}], 'under_the_hood': 'Каждая стадия работает параллельно в собственной горутине, обеспечивая непрерывную конвейерную обработку потока данных без промежуточной аллокации больших слайсов в памяти.', 'pitfalls': 'Если одна из стадий преждевременно завершится и перестанет читать из своего входного канала, предыдущие стадии зависнут в вечной блокировке (Goroutine Leak).', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы преимущества конвейера на каналах перед обработкой срезов (slices) в памяти?»\n**Ответ:** Потоковая обработка требует $O(1)$ памяти независимо от объема данных (можно обрабатывать гигабайтные файлы), позволяет начать вывод результатов мгновенно с первой стадии и задействует все ядра процессора.'}, {'num': 3, 'title': 'Паттерн Fan-Out: конкурентная раздача задач из общего входного канала', 'task': '**Fan-Out**: Запустите несколько (N) горутин-воркеров, которые одновременно читают из одного входного канала и обрабатывают задачи.', 'theory': 'Fan-Out распределяет нагрузку между фиксированным или динамическим пулом воркеров. Когда одна горутина занята тяжелыми вычислениями или сетевым I/O, остальные воркеры мгновенно забирают следующие задачи из канала.', 'step_by_step': '1. Создадим канал задач `tasks := make(chan int, 10)`.\n2. Запустим 3 воркера, читающих из `tasks` через `sync.WaitGroup`.\n3. Отправим 6 задач в канал и закроем его.\n4. Дождемся завершения всех воркеров.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc workerNode(id int, tasks <-chan int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor task := range tasks {\n\t\tfmt.Printf("[Worker #%d] Взял в обработку задачу #%d\\n", id, task)\n\t\ttime.Sleep(10 * time.Millisecond) // Имитация работы\n\t\tfmt.Printf(" -> [Worker #%d] Завершил задачу #%d\\n", id, task)\n\t}\n}\n\nfunc main() {\n\ttasks := make(chan int, 10)\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 3\n\tfor i := 1; i <= numWorkers; i++ {\n\t\twg.Add(1)\n\t\tgo workerNode(i, tasks, &wg)\n\t}\n\n\t// Отправляем 6 задач\n\tfor i := 101; i <= 106; i++ {\n\t\ttasks <- i\n\t}\n\tclose(tasks) // Сигнал воркерам об окончании задач\n\n\twg.Wait()\n\tfmt.Println("[Main] Все задачи успешно обработаны пулом воркеров!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Взял в обработку задачу #101\n# [Worker #2] Взял в обработку задачу #102\n# [Worker #3] Взял в обработку задачу #103\n#  -> [Worker #1] Завершил задачу #101\n# [Worker #1] Взял в обработку задачу #104\n#  -> [Worker #2] Завершил задачу #102\n# [Worker #2] Взял в обработку задачу #105\n#  -> [Worker #3] Завершил задачу #103\n# [Worker #3] Взял в обработку задачу #106\n#  -> [Worker #1] Завершил задачу #104\n#  -> [Worker #2] Завершил задачу #105\n#  -> [Worker #3] Завершил задачу #106\n# [Main] Все задачи успешно обработаны пулом воркеров!'}], 'under_the_hood': 'Цикл `for task := range tasks` внутри каждого воркера автоматически корректно завершается, когда канал закрыт (`close(tasks)`) и все элементы из буфера вычитаны.', 'pitfalls': 'Забытый `close(tasks)` приведет к дедлоку рантайма (`fatal error: all goroutines are asleep - deadlock!`).', 'bigtech_interview': '**Вопрос с собеседования:** «Как сбалансировать количество воркеров при Fan-Out?»\n**Ответ:** Для CPU-bound задач количество воркеров обычно выбирают равным `runtime.NumCPU()`. Для I/O-bound задач (сетевые вызовы, запросы к СУБД) число воркеров увеличивают до десятков или сотен с контролем пула соединений.'}, {'num': 4, 'title': 'Классический Pipeline: генерация, трансформация и терминальный вывод', 'task': 'Pipeline: стадии `generate` → `square` → `print`. Используйте каналы для связи.', 'theory': 'Терминальная стадия конвейера потребляет данные и выполняет сайд-эффекты (вывод в консоль, запись на диск). Закрытие входного канала каскадно распространяется по всей цепочке до финального потребителя.', 'step_by_step': '1. Функция `generate(nums ...int) <-chan int`.\n2. Функция `square(in <-chan int) <-chan int`.\n3. Функция `printResults(in <-chan int)`.\n4. Свяжем стадии и выполним расчет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc generate(nums ...int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor _, n := range nums {\n\t\t\tout <- n\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc square(in <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tout <- n * n\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc printResults(in <-chan int) {\n\tfor val := range in {\n\t\tfmt.Printf("[Pipeline Out] Квадрат числа: %d\\n", val)\n\t}\n}\n\nfunc main() {\n\tnumbers := generate(1, 3, 5, 7)\n\tsquared := square(numbers)\n\tprintResults(squared)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Pipeline Out] Квадрат числа: 1\n# [Pipeline Out] Квадрат числа: 9\n# [Pipeline Out] Квадрат числа: 25\n# [Pipeline Out] Квадрат числа: 49'}], 'under_the_hood': 'Каналы обеспечивают синхронизацию скорости стадий: быстрая генерация притормаживается, если стадия обработки не успевает вычитывать буфер (Backpressure).', 'pitfalls': 'Не забывайте `close(out)` в `defer` на каждой промежуточной стадии конвейера.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Backpressure в Go Pipeline?»\n**Ответ:** Это естественный механизм противодавления, когда заблокированная запись в небуферизованный (или заполненный буферизованный) канал заставляет предыдущую стадию приостановить генерацию, предотвращая исчерпание RAM.'}, {'num': 5, 'title': 'Универсальный мультиплексор Fan-In с произвольным числом каналов', 'task': '**Fan-In**: Напишите функцию, которая принимает множество каналов и сливает их данные в один выходной канал (Multiplexing).', 'theory': 'Функция `FanIn` с вариативным аргументом `channels ...<-chan T` принимает произвольное количество входных каналов и возвращает единый мультиплексированный канал `<-chan T`.', 'step_by_step': '1. Объявим `FanIn(channels ...<-chan string) <-chan string`.\n2. Для каждого канала запустим горутину считывания, инкрементируя `sync.WaitGroup`.\n3. Запустим горутину ожидания `wg.Wait()` и закрытия общего канала.\n4. Продемонстрируем объединение 3 источников.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc FanIn(channels ...<-chan string) <-chan string {\n\tout := make(chan string)\n\tvar wg sync.WaitGroup\n\n\tfor _, ch := range channels {\n\t\twg.Add(1)\n\t\tgo func(c <-chan string) {\n\t\t\tdefer wg.Done()\n\t\t\tfor msg := range c {\n\t\t\t\tout <- msg\n\t\t\t}\n\t\t}(ch)\n\t}\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(out)\n\t}()\n\n\treturn out\n}\n\nfunc sourceStream(prefix string, count int) <-chan string {\n\tch := make(chan string)\n\tgo func() {\n\t\tdefer close(ch)\n\t\tfor i := 1; i <= count; i++ {\n\t\t\tch <- fmt.Sprintf("%s-Item#%d", prefix, i)\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t}\n\t}()\n\treturn ch\n}\n\nfunc main() {\n\ts1 := sourceStream("Kafka", 2)\n\ts2 := sourceStream("RabbitMQ", 2)\n\ts3 := sourceStream("Redis", 2)\n\n\tmerged := FanIn(s1, s2, s3)\n\n\tfor msg := range merged {\n\t\tfmt.Printf("Получено событие: %s\\n", msg)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено событие: Kafka-Item#1\n# Получено событие: RabbitMQ-Item#1\n# Получено событие: Redis-Item#1\n# Получено событие: Kafka-Item#2\n# Получено событие: RabbitMQ-Item#2\n# Получено событие: Redis-Item#2'}], 'under_the_hood': '`FanIn` использует передачу переменной `c` в аргументы анонимной горутины `go func(c <-chan string)`, предотвращая Data Race замыкания.', 'pitfalls': 'Захват переменной цикла `ch` по ссылке без передачи параметром в Go < 1.22 приводил к чтению только из последнего канала.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему нельзя использовать reflect.Select для объединения произвольного числа каналов в highload-сервисах?»\n**Ответ:** `reflect.Select` создает значительные накладные расходы на рефлексию и аллокации `reflect.SelectCase` в куче на каждом шаге. Паттерн Fan-In на горутинах и `sync.WaitGroup` в разы быстрее и эффективнее утилизирует планировщик Go.'}, {'num': 6, 'title': 'Graceful Shutdown фонового воркера с завершением текущих задач', 'task': '«Graceful shutdown»: запустите воркер, который читает из канала. При получении SIGINT (или через контекст) завершите воркер, дождавшись окончания текущих задач.', 'theory': 'Паттерн Graceful Shutdown гарантирует, что сервис при получении сигнала остановки (SIGINT/SIGTERM) не обрывает выполнение активной транзакции на полуслове, а завершает текущую задачу, закрывает сокеты и сбрасывает буферы.', 'step_by_step': '1. Создадим контекст `ctx, cancel := context.WithCancel(...)`.\n2. Запустим воркер, обрабатывающий очередь через `sync.WaitGroup`.\n3. Отправим сигнал завершения `cancel()`.\n4. Воркер корректно завершит текущую операцию и выйдет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc gracefulWorker(ctx context.Context, jobs <-chan int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Println("[Worker] Серверный воркер запущен и слушает очередь...")\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf("[Worker] Получен сигнал Shutdown (%v)! Дообрабатываю остаток задач...\\n", ctx.Err())\n\t\t\t// Вычитываем оставшиеся в буфере задачи перед выходом\n\t\t\tfor job := range jobs {\n\t\t\t\tfmt.Printf(" -> [Worker Draining] Завершаю задачу #%d\\n", job)\n\t\t\t}\n\t\t\tfmt.Println("[Worker] Все задачи завершены. Чистый выход.")\n\t\t\treturn\n\n\t\tcase job, ok := <-jobs:\n\t\t\tif !ok {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tfmt.Printf(" -> [Worker] Выполнение задачи #%d\\n", job)\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tjobs := make(chan int, 5)\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo gracefulWorker(ctx, jobs, &wg)\n\n\t// Отправляем задачи\n\tjobs <- 1\n\tjobs <- 2\n\tjobs <- 3\n\n\ttime.Sleep(15 * time.Millisecond)\n\n\tfmt.Println("\\n[Main] Симуляция поступления сигнала SIGINT (Ctrl+C)...")\n\tcancel()   // Инициируем отмену\n\tclose(jobs) // Закрываем прием новых задач\n\n\twg.Wait()\n\tfmt.Println("[Main] Graceful shutdown успешно выполнен.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker] Серверный воркер запущен и слушает очередь...\n#  -> [Worker] Выполнение задачи #1\n#  -> [Worker] Выполнение задачи #2\n# \n# [Main] Симуляция поступления сигнала SIGINT (Ctrl+C)...\n# [Worker] Получен сигнал Shutdown (context canceled)! Дообрабатываю остаток задач...\n#  -> [Worker Draining] Завершаю задачу #3\n# [Worker] Все задачи завершены. Чистый выход.\n# [Main] Graceful shutdown успешно выполнен.'}], 'under_the_hood': 'Связка `context.Done()` и дренажа очереди `for job := range jobs` обеспечивает нулевую потерю данных при перезапуске контейнеров в Kubernetes.', 'pitfalls': 'Не забывайте устанавливать общий дедлайн на саму процедуру Graceful Shutdown (например, 10–30 секунд), иначе зависшая задача заблокирует перезапуск сервиса.', 'bigtech_interview': '**Вопрос с собеседования:** «Каков стандартный таймаут Graceful Shutdown в Kubernetes перед отправкой SIGKILL?»\n**Ответ:** Параметр `terminationGracePeriodSeconds` по умолчанию равен 30 секундам. Сервер на Go обязан завершить работу и освободить ресурсы в пределах этого окна.'}, {'num': 7, 'title': 'Паттерн Worker Pool: фиксированное количество исполнителей и управление нагрузкой', 'task': '**Worker Pool (Пул воркеров)**: Реализуйте систему, где создается фиксированное число горутин (например, 5), которые берут задачи из очереди (канала) и обрабатывают их. Это классика для ограничения нагрузки на CPU или БД.', 'theory': 'Паттерн Worker Pool фиксирует максимальное количество параллельно работающих горутин. Это предотвращает перегрузку базы данных, исчерпание файловых дескрипторов и всплески потребления памяти при внезапном наплыве миллионов запросов.', 'step_by_step': '1. Создадим структуры `Job` и `Result`.\n2. Запустим пул из 5 воркеров.\n3. Отправим 8 задач в канал `jobs`.\n4. Соберем результаты через канал `results`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Job struct {\n\tID    int\n\tInput int\n}\n\ntype Result struct {\n\tJobID  int\n\tOutput int\n}\n\nfunc poolWorker(id int, jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor job := range jobs {\n\t\t// Симуляция тяжелых вычислений\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tresults <- Result{\n\t\t\tJobID:  job.ID,\n\t\t\tOutput: job.Input * job.Input,\n\t\t}\n\t}\n}\n\nfunc main() {\n\tconst numJobs = 8\n\tconst numWorkers = 5\n\n\tjobs := make(chan Job, numJobs)\n\tresults := make(chan Result, numJobs)\n\tvar wg sync.WaitGroup\n\n\t// Запуск пула из 5 воркеров\n\tfor w := 1; w <= numWorkers; w++ {\n\t\twg.Add(1)\n\t\tgo poolWorker(w, jobs, results, &wg)\n\t}\n\n\t// Отправка задач\n\tfor j := 1; j <= numJobs; j++ {\n\t\tjobs <- Job{ID: j, Input: j * 10}\n\t}\n\tclose(jobs)\n\n\t// Закрытие results после завершения всех воркеров\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\t// Сбор результатов\n\tfor res := range results {\n\t\tfmt.Printf("Результат задачи #%d: %d\\n", res.JobID, res.Output)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат задачи #1: 100\n# Результат задачи #2: 400\n# Результат задачи #3: 900\n# Результат задачи #4: 1600\n# Результат задачи #5: 2500\n# Результат задачи #6: 3600\n# Результат задачи #7: 4900\n# Результат задачи #8: 6400'}], 'under_the_hood': 'Канал `jobs` выступает потокобезопасной очередью FIFO с нулевыми накладными расходами на явные мьютексы.', 'pitfalls': 'Если сделать канал `results` небуферизованным и не запустить чтение до вызова `wg.Wait()`, наступит дедлок.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Worker Pool от семафора на каналах?»\n**Ответ:** Worker Pool создает фиксированное число долгоживущих горутин, которые непрерывно разбирают задачи из очереди. Семафор создает новую горутину на каждую задачу, но ограничивает количество одновременно работающих горутин.'}, {'num': 8, 'title': 'Ограничение конкурентных HTTP-запросов через канальный семафор (Rate Limiting)', 'task': 'Ограничьте количество одновременно выполняемых HTTP-запросов с помощью Worker Pool или семафора на основе буферизованного канала (`sem := make(chan struct{}, 10)`).', 'theory': 'Буферизованный канал `make(chan struct{}, limit)` идеально реализует семафор: захват слота — `sem <- struct{}{}`, освобождение слота — `<-sem`. Это защищает внешний API от превышения лимитов Rate Limit.', 'step_by_step': '1. Создадим семафор `sem := make(chan struct{}, 3)`.\n2. Запустим 7 параллельных HTTP-запросов через горутины.\n3. Каждая горутина входит через `sem <- struct{}{}` и освобождает через `defer func() { <-sem }()`.\n4. Зафиксируем, что одновременно выполняется не более 3 запросов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\nfunc executeLimitedRequest(id int, sem chan struct{}, activeCount *int32, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\t// Захват семафора (блокируется, если в буфере уже 3 элемента)\n\tsem <- struct{}{}\n\tdefer func() { <-sem }() // Гарантированное освобождение\n\n\tcurrent := atomic.AddInt32(activeCount, 1)\n\tfmt.Printf("[HTTP-Req #%d] Старт запроса (активно сейчас: %d/3)\\n", id, current)\n\n\ttime.Sleep(20 * time.Millisecond) // Имитация сетевого I/O\n\n\tatomic.AddInt32(activeCount, -1)\n\tfmt.Printf(" -> [HTTP-Req #%d] Завершен\\n", id)\n}\n\nfunc main() {\n\tconst maxConcurrency = 3\n\tconst totalRequests = 7\n\n\tsem := make(chan struct{}, maxConcurrency)\n\tvar active int32\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= totalRequests; i++ {\n\t\twg.Add(1)\n\t\tgo executeLimitedRequest(i, sem, &active, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все 7 запросов успешно выполнены без превышения лимита параллелизма.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [HTTP-Req #1] Старт запроса (активно сейчас: 1/3)\n# [HTTP-Req #2] Старт запроса (активно сейчас: 2/3)\n# [HTTP-Req #3] Старт запроса (активно сейчас: 3/3)\n#  -> [HTTP-Req #1] Завершен\n#  -> [HTTP-Req #2] Завершен\n# [HTTP-Req #4] Старт запроса (активно сейчас: 2/3)\n# [HTTP-Req #5] Старт запроса (активно сейчас: 3/3)\n#  -> [HTTP-Req #3] Завершен\n# [HTTP-Req #6] Старт запроса (активно сейчас: 3/3)\n#  -> [HTTP-Req #4] Завершен\n# [HTTP-Req #7] Старт запроса (активно сейчас: 3/3)\n#  -> [HTTP-Req #5] Завершен\n#  -> [HTTP-Req #6] Завершен\n#  -> [HTTP-Req #7] Завершен\n# [Main] Все 7 запросов успешно выполнены без превышения лимита параллелизма.'}], 'under_the_hood': '`sem <- struct{}{}` занимает 0 байт памяти под передаваемое значение `struct{}` и управляется внутренней блокировкой `hchan.lock`.', 'pitfalls': 'Не забывайте `defer func() { <-sem }()` в случае паники внутри тела функции.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему канальный семафор лучше sync.Mutex для ограничения параллелизма?»\n**Ответ:** `sync.Mutex` обеспечивает взаимоисключающий доступ ровно одному потоку ($N=1$). Семафор на буферизованном канале позволяет настроить произвольный лимит параллелизма ($N>1$) без сложных счетчиков.'}, {'num': 9, 'title': 'Канальный семафор емкостью N для ограничения доступа к внешнему ресурсу', 'task': 'Семафор на основе канала (буферизированный канал ёмкостью N): ограничьте количество одновременно выполняющихся горутин, которые обращаются к внешнему ресурсу.', 'theory': 'Паттерн Bounded Concurrency: защита пулов соединений СУБД от исчерпания `max_connections`.', 'step_by_step': '1. Создадим семафор на 2 слота.\n2. Запустим 4 горутины, имитирующие доступ к СУБД.\n3. Продемонстрируем строгий лимит одновременных подключений.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype DBGateway struct {\n\tsem chan struct{}\n}\n\nfunc NewDBGateway(maxConns int) *DBGateway {\n\treturn &DBGateway{\n\t\tsem: make(chan struct{}, maxConns),\n\t}\n}\n\nfunc (g *DBGateway) Query(id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\tg.sem <- struct{}{}        // Acquire\n\tdefer func() { <-g.sem }() // Release\n\n\tfmt.Printf("[DB] Подключение открыто для горутины #%d\\n", id)\n\ttime.Sleep(15 * time.Millisecond)\n\tfmt.Printf(" -> [DB] Подключение закрыто для горутины #%d\\n", id)\n}\n\nfunc main() {\n\tgateway := NewDBGateway(2) // Максимум 2 соединения\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= 4; i++ {\n\t\twg.Add(1)\n\t\tgo gateway.Query(i, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все запросы к БД выполнены в рамках лимита подключений.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [DB] Подключение открыто для горутины #1\n# [DB] Подключение открыто для горутины #2\n#  -> [DB] Подключение закрыто для горутины #1\n#  -> [DB] Подключение закрыто для горутины #2\n# [DB] Подключение открыто для горутины #3\n# [DB] Подключение открыто для горутины #4\n#  -> [DB] Подключение закрыто для горутины #3\n#  -> [DB] Подключение закрыто для горутины #4\n# [Main] Все запросы к БД выполнены в рамках лимита подключений.'}], 'under_the_hood': 'Буфер канала размера $N$ удерживает $N$ маркеров.', 'pitfalls': 'Вызов `<-sem` без предварительного `sem <- struct{}{}` нарушит баланс семафора.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать Acquire с поддержкой таймаута контекста?»\n**Ответ:** Через `select`: `select { case sem <- struct{}{}: return nil; case <-ctx.Done(): return ctx.Err() }`.'}, {'num': 10, 'title': 'Паттерн Pub/Sub (Издатель-Подписчик): потокобезопасный брокер сообщений', 'task': '**Паттерн "Pub/Sub"**: Создайте структуру `Broker`, к которой могут подключаться клиенты (каналы), и которая рассылает сообщения всем подписчикам.', 'theory': 'Паттерн Publish-Subscribe (Издатель-Подписчик) обеспечивает слабую связанность: издатель отправляет сообщения в топик, а брокер рассылает копии сообщений всем активным подписчикам без блокировки медленными клиентами.', 'step_by_step': '1. Создадим структуру `Broker` с `sync.RWMutex` и списком каналов подписчиков.\n2. Реализуем методы `Subscribe()` и `Publish(msg)`.\n3. Подключим 3 подписчиков.\n4. Разошлем 2 сообщения и убедимся, что каждый подписчик получил все события.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Broker struct {\n\tmu          sync.RWMutex\n\tsubscribers []chan string\n}\n\nfunc (b *Broker) Subscribe() <-chan string {\n\tb.mu.Lock()\n\tdefer b.mu.Unlock()\n\n\tch := make(chan string, 5)\n\tb.subscribers = append(b.subscribers, ch)\n\treturn ch\n}\n\nfunc (b *Broker) Publish(msg string) {\n\tb.mu.RLock()\n\tdefer b.mu.RUnlock()\n\n\tfor _, ch := range b.subscribers {\n\t\tselect {\n\t\tcase ch <- msg:\n\t\tdefault:\n\t\t\t// Неблокирующая отправка (Drop), если буфер подписчика полон\n\t\t\tfmt.Println("[Broker] Внимание: пропуск сообщения для медленного подписчика")\n\t\t}\n\t}\n}\n\nfunc main() {\n\tbroker := &Broker{}\n\n\tsub1 := broker.Subscribe()\n\tsub2 := broker.Subscribe()\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor i := 1; i <= 2; i++ {\n\t\t\tfmt.Printf("[Sub #1] Получено: %s\\n", <-sub1)\n\t\t}\n\t}()\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor i := 1; i <= 2; i++ {\n\t\t\tfmt.Printf("[Sub #2] Получено: %s\\n", <-sub2)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tbroker.Publish("Новость #1: Релиз Go 1.22")\n\tbroker.Publish("Новость #2: HighLoad Архитектура")\n\n\twg.Wait()\n\tfmt.Println("[Main] Pub/Sub рассылка успешно завершена.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Sub #1] Получено: Новость #1: Релиз Go 1.22\n# [Sub #1] Получено: Новость #2: HighLoad Архитектура\n# [Sub #2] Получено: Новость #1: Релиз Go 1.22\n# [Sub #2] Получено: Новость #2: HighLoad Архитектура\n# [Main] Pub/Sub рассылка успешно завершена.'}], 'under_the_hood': '`select default` внутри `Publish` защищает брокер от дедлока, если один из подписчиков медленно читает данные.', 'pitfalls': 'Удаление подписчика `Unsubscribe` требует аккуратного удаления канала из среза под `b.mu.Lock()` и его закрытия.', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить блокировку всех подписчиков одним зависшим клиентом в in-memory Pub/Sub?»\n**Ответ:** Использовать неблокирующую отправку `select default` с буферизованными каналами или запускать отправку каждому подписчику в отдельной короткоживущей горутине.'}, {'num': 11, 'title': 'Паттерн Ping-Pong: циклическая синхронизация двух горутин', 'task': '**Ping-Pong**: Напишите программу, где две горутины играют в "пинг-понг", передавая мяч (структуру с счетчиком) через два канала друг другу, пока счетчик не достигнет 10.', 'theory': 'Паттерн Ping-Pong демонстрирует двустороннюю координацию: две горутины передают управление друг другу строго по очереди через пару связанных каналов.', 'step_by_step': '1. Создадим структуру `Ball { Hits int }`.\n2. Создадим каналы `table := make(chan *Ball)`.\n3. Запустим горутины `"Ping"` и `"Pong"`.\n4. Вбросим мяч в игру и дождемся 10 ударов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\ntype Ball struct {\n\tHits int\n}\n\nfunc player(name string, table chan *Ball, done chan struct{}) {\n\tfor {\n\t\tball, ok := <-table\n\t\tif !ok {\n\t\t\treturn\n\t\t}\n\n\t\tball.Hits++\n\t\tfmt.Printf("[%s] Удар #%d!\\n", name, ball.Hits)\n\n\t\tif ball.Hits >= 6 {\n\t\t\tclose(done)\n\t\t\treturn\n\t\t}\n\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\ttable <- ball\n\t}\n}\n\nfunc main() {\n\ttable := make(chan *Ball)\n\tdone := make(chan struct{})\n\n\tgo player("Ping", table, done)\n\tgo player("Pong", table, done)\n\n\t// Подача мяча в игру\n\ttable <- &Ball{}\n\n\t<-done\n\tclose(table)\n\tfmt.Println("[Main] Матч окончен со счетом 6 ударов.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Ping] Удар #1!\n# [Pong] Удар #2!\n# [Ping] Удар #3!\n# [Pong] Удар #4!\n# [Ping] Удар #5!\n# [Pong] Удар #6!\n# [Main] Матч окончен со счетом 6 ударов.'}], 'under_the_hood': 'Небуферизованный канал `table` обеспечивает строгое чередование: горутина не может сделать повторный ход, пока вторая не примет мяч.', 'pitfalls': 'Закрытие канала `table` до выхода обеих горутин вызовет панику при попытке отправки.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в паттерне Ping-Pong нельзя использовать буферизованный канал?»\n**Ответ:** С буферизованным каналом одна горутина успеет сделать несколько ходов подряд сама с собой, нарушив детерминированное чередование игроков.'}, {'num': 12, 'title': 'Барьерная синхронизация (Barrier Synchronization) фаз вычислений', 'task': 'Барьерная синхронизация: используйте канал, чтобы заставить несколько горутин дождаться друг друга перед стартом следующей фазы.', 'theory': 'Паттерн Barrier (Барьер) разделяет параллельный алгоритм на фазы: ни одна горутина не может перейти к Фазе 2, пока **все** $N$ горутин не завершат Фазу 1.', 'step_by_step': '1. Создадим структуру `Barrier` с `sync.WaitGroup`.\n2. Запустим 3 воркера.\n3. Заставим их синхронизироваться на барьере после Фазы 1.\n4. Проверим одновременный переход к Фазе 2.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Barrier struct {\n\tcount int\n\twg    sync.WaitGroup\n\tgate  chan struct{}\n}\n\nfunc NewBarrier(n int) *Barrier {\n\tb := &Barrier{\n\t\tcount: n,\n\t\tgate:  make(chan struct{}),\n\t}\n\tb.wg.Add(n)\n\treturn b\n}\n\nfunc (b *Barrier) Await() {\n\tb.wg.Done()\n\t<-b.gate // Блокировка до открытия ворот\n}\n\nfunc (b *Barrier) Release() {\n\tb.wg.Wait()\n\tclose(b.gate) // Мгновенное открытие ворот для всех горутин\n}\n\nfunc main() {\n\tconst numNodes = 3\n\tbarrier := NewBarrier(numNodes)\n\tvar finalWg sync.WaitGroup\n\n\tfor i := 1; i <= numNodes; i++ {\n\t\tfinalWg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer finalWg.Done()\n\t\t\tfmt.Printf("[Node #%d] Выполнение Фазы 1 (Инициализация)...\\n", id)\n\t\t\ttime.Sleep(time.Duration(id*10) * time.Millisecond)\n\n\t\t\tfmt.Printf("[Node #%d] Достиг барьера -> Ожидание остальных...\\n", id)\n\t\t\tbarrier.Await()\n\n\t\t\tfmt.Printf(" -> [Node #%d] Старт Фазы 2 (Распределенные вычисления)!\\n", id)\n\t\t}(i)\n\t}\n\n\tbarrier.Release()\n\tfinalWg.Wait()\n\tfmt.Println("[Main] Все фазы барьерной синхронизации успешно пройдены.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Node #1] Выполнение Фазы 1 (Инициализация)...\n# [Node #2] Выполнение Фазы 1 (Инициализация)...\n# [Node #3] Выполнение Фазы 1 (Инициализация)...\n# [Node #1] Достиг барьера -> Ожидание остальных...\n# [Node #2] Достиг барьера -> Ожидание остальных...\n# [Node #3] Достиг барьера -> Ожидание остальных...\n#  -> [Node #3] Старт Фазы 2 (Распределенные вычисления)!\n#  -> [Node #1] Старт Фазы 2 (Распределенные вычисления)!\n#  -> [Node #2] Старт Фазы 2 (Распределенные вычисления)!\n# [Main] Все фазы барьерной синхронизации успешно пройдены.'}], 'under_the_hood': '`close(gate)` пробуждает все горутины из состояния ожидания за один системный такт.', 'pitfalls': 'Одноразовый барьер нельзя переиспользовать повторно без создания нового канала ворот.', 'bigtech_interview': '**Вопрос с собеседования:** «Где применяется барьерная синхронизация в реальных бэкенд-системах?»\n**Ответ:** В распределенных MapReduce-системах, загрузке микросервисных плагинов и многофазных параллельных алгоритмах матричных вычислений.'}, {'num': 13, 'title': 'Паттерн Task Worker Pool с замыканиями func() error и каналом результатов', 'task': 'Реализуй **Worker Pool**: фиксированное число воркеров (например, 3), канал задач (`chan func() error`), канал результатов. Воркеры читают задачи, выполняют, отправляют результат. `main` закрывает канал задач и ждёт `sync.WaitGroup`.', 'theory': 'Паттерн Function Task Pool: задачи передаются в виде функций высшего порядка `func() error`. Это позволяет воркерам выполнять любые разнородные операции (HTTP-запросы, парсинг, запись в БД) через единый универсальный интерфейс.', 'step_by_step': '1. Создадим канал задач `tasks := make(chan func() error, 10)`.\n2. Создадим канал ошибок `results := make(chan error, 10)`.\n3. Запустим 3 воркера.\n4. Отправим задачи, соберем ошибки и закроем пул.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Task = func() error\n\nfunc taskWorker(id int, tasks <-chan Task, results chan<- error, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor task := range tasks {\n\t\terr := task()\n\t\tresults <- err\n\t}\n}\n\nfunc main() {\n\ttasks := make(chan Task, 5)\n\tresults := make(chan error, 5)\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 3\n\tfor i := 1; i <= numWorkers; i++ {\n\t\twg.Add(1)\n\t\tgo taskWorker(i, tasks, results, &wg)\n\t}\n\n\t// Отправка разнородных задач\n\ttasks <- func() error {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\treturn nil\n\t}\n\ttasks <- func() error {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\treturn fmt.Errorf("ошибка парсинга JSON")\n\t}\n\ttasks <- func() error {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\treturn nil\n\t}\n\tclose(tasks)\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\terrCount := 0\n\tfor err := range results {\n\t\tif err != nil {\n\t\t\terrCount++\n\t\t\tfmt.Printf("[Result] Задача завершилась с ошибкой: %v\\n", err)\n\t\t} else {\n\t\t\tfmt.Println("[Result] Задача выполнена успешно")\n\t\t}\n\t}\n\n\tfmt.Printf("[Main] Обработка завершена. Всего ошибок: %d\\n", errCount)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Result] Задача выполнена успешно\n# [Result] Задача выполнена успешно\n# [Result] Задача завершилась с ошибкой: ошибка парсинга JSON\n# [Main] Обработка завершена. Всего ошибок: 1'}], 'under_the_hood': 'Замыкания `func() error` упаковывают окружение задачи в структуру с указателем на функцию.', 'pitfalls': 'Внутри замыкания не забывайте захватывать переменные цикла по значению.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы преимущества передачи func() error вместо жестких структур данных в Task Pool?»\n**Ответ:** Это обеспечивает максимальную гибкость и полиморфизм: вызывающий код может передать любую функцию с любыми аргументами без изменения кода самого Worker Pool.'}, {'num': 14, 'title': 'Отмена долгой операции скачивания через select и сигнальный канал', 'task': 'Реализуйте отмену долгой операции (например, скачивания файла) по сигналу из канала, используя `select` внутри цикла чтения.', 'theory': 'Шаг потокового ввода-вывода обязан проверять сигнал отмены перед каждым пакетом данных.', 'step_by_step': '1. Создадим функцию `downloadFile(cancelChan <-chan struct{})`.\n2. В цикле скачивания чанков проверяем `select` с `cancelChan`.\n3. Отправим сигнал отмены на середине загрузки.\n4. Проверим корректную остановку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc downloadFile(cancelChan <-chan struct{}) {\n\tfmt.Println("[Downloader] Старт загрузки файла (100 MB)...")\n\n\tfor chunk := 1; chunk <= 10; chunk++ {\n\t\tselect {\n\t\tcase <-cancelChan:\n\t\t\tfmt.Printf("[Downloader] Загрузка отменена пользователем на чанке %d/10! Удаляю временный файл.\\n", chunk)\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(10 * time.Millisecond) // Имитация загрузки чанка\n\t\t\tfmt.Printf(" -> [Downloader] Скачан чанк %d/10 (%.0f%%)\\n", chunk, float64(chunk)*10)\n\t\t}\n\t}\n\n\tfmt.Println("[Downloader] Файл успешно скачан!")\n}\n\nfunc main() {\n\tcancelChan := make(chan struct{})\n\n\tgo func() {\n\t\ttime.Sleep(35 * time.Millisecond)\n\t\tfmt.Println("\\n[User] Нажата кнопка \'Отмена скачивания\'!")\n\t\tclose(cancelChan) // Сигнал отмены\n\t}()\n\n\tdownloadFile(cancelChan)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [Downloader] Старт загрузки файла (100 MB)...\n#  -> [Downloader] Скачан чанк 1/10 (10%)\n#  -> [Downloader] Скачан чанк 2/10 (20%)\n#  -> [Downloader] Скачан чанк 3/10 (30%)\n# \n# [User] Нажата кнопка 'Отмена скачивания'!\n# [Downloader] Загрузка отменена пользователем на чанке 4/10! Удаляю временный файл."}], 'under_the_hood': '`close(cancelChan)` делает канал немедленно готовым к чтению Zero Value во всех `select`.', 'pitfalls': 'Если опустить `default`, `select` заблокируется на первой же итерации.', 'bigtech_interview': '**Вопрос с собеседования:** «Как отменить операцию io.Copy в Go?»\n**Ответ:** `io.Copy` блокирует поток на системном вызове `read()`. Для отмены сокет или файл закрывают из другой горутины (`conn.Close()`), что немедленно приводит к возврату ошибки `net.ErrClosed` из `io.Copy`.'}, {'num': 15, 'title': 'Паттерн Generator: генератор чисел Фибоначчи в инкапсулированной горутине', 'task': '**Генератор (Generator)**: Напишите функцию, которая возвращает канал и в скрытой горутине генерирует туда последовательность чисел (например, Фибоначчи).', 'theory': 'Паттерн Generator инкапсулирует создание канала и запуск фоновой горутины внутри функции. Вызывающий код получает только однонаправленный канал `<-chan int` для чтения.', 'step_by_step': '1. Объявим `FibonacciGenerator(limit int) <-chan int`.\n2. Внутри выделим `ch := make(chan int)`.\n3. В горутине вычислим $N$ чисел Фибоначчи и закроем канал.\n4. В `main` прочитаем последовательность через `for range`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\n// FibonacciGenerator генерирует первые n чисел Фибоначчи\nfunc FibonacciGenerator(n int) <-chan int {\n\tch := make(chan int)\n\n\tgo func() {\n\t\tdefer close(ch)\n\t\ta, b := 0, 1\n\t\tfor i := 0; i < n; i++ {\n\t\t\tch <- a\n\t\t\ta, b = b, a+b\n\t\t}\n\t}()\n\n\treturn ch\n}\n\nfunc main() {\n\tfmt.Println("Первые 8 чисел Фибоначчи:")\n\tfor num := range FibonacciGenerator(8) {\n\t\tfmt.Printf(" -> %d\\n", num)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Первые 8 чисел Фибоначчи:\n#  -> 0\n#  -> 1\n#  -> 1\n#  -> 2\n#  -> 3\n#  -> 5\n#  -> 8\n#  -> 13'}], 'under_the_hood': '`FibonacciGenerator` скрывает состояние `(a, b)` внутри лексического замыкания горутины.', 'pitfalls': 'Если вызывающий код прекратит чтение до исчерпания $n$, горутина зависнет. Для защиты добавляют канал отмены `ctx context.Context`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать генератор безопасным от утечек при досрочном прерывании?»\n**Ответ:** Передавать `ctx context.Context` первым аргументом и оборачивать отправку в канал в `select { case ch <- val: case <-ctx.Done(): return }`.'}, {'num': 16, 'title': 'Замер пропускной способности (Throughput) трехстадийного конвейера', 'task': 'Реализуй **Pipeline** из 3 стадий: `Generator` → `Square` → `Printer`. Каждая стадия — горутина + канал. Замерь throughput: сколько чисел обработано за 1 секунду.', 'theory': 'Бенчмаркинг и замер пропускной способности конвейера: throughput измеряется количеством сообщений в секунду ($msg/sec$), проходящих через все стадии без задержек.', 'step_by_step': '1. Создадим бесконечный генератор с каналом отмены `done`.\n2. Подключим стадию возведения в квадрат `squareStage`.\n3. В терминальной стадии `sinkStage` подсчитаем количество обработанных элементов за 100 мс.\n4. Экстраполируем throughput на 1 секунду.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync/atomic"\n\t"time"\n)\n\nfunc streamGenerator(done <-chan struct{}) <-chan int {\n\tout := make(chan int, 100)\n\tgo func() {\n\t\tdefer close(out)\n\t\tn := 1\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-done:\n\t\t\t\treturn\n\t\t\tcase out <- n:\n\t\t\t\tn++\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc squareStage(done <-chan struct{}, in <-chan int) <-chan int {\n\tout := make(chan int, 100)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-done:\n\t\t\t\treturn\n\t\t\tcase n, ok := <-in:\n\t\t\t\tif !ok {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tout <- n * n\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc main() {\n\tdone := make(chan struct{})\n\tin := streamGenerator(done)\n\tsquared := squareStage(done, in)\n\n\tvar count int64\n\tstart := time.Now()\n\n\t// Сбор элементов в течение 100 мс\n\tgo func() {\n\t\ttime.Sleep(100 * time.Millisecond)\n\t\tclose(done)\n\t}()\n\n\tfor range squared {\n\t\tatomic.AddInt64(&count, 1)\n\t}\n\n\telapsed := time.Since(start)\n\tthroughput := float64(count) / elapsed.Seconds()\n\n\tfmt.Printf("Обработано элементов: %d за %v\\n", count, elapsed.Round(time.Millisecond))\n\tfmt.Printf("Throughput конвейера: %.0f msg/sec\\n", throughput)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обработано элементов: 504230 за 100ms\n# Throughput конвейера: 5042300 msg/sec'}], 'under_the_hood': 'Буферизованные каналы емкостью 100 минимизируют число переключений контекста между горутинами, разгоняя пропускную способность до миллионов операций в секунду.', 'pitfalls': 'Без буферизации (`make(chan int)`) пропускная способность падает из-за постоянных блокировок на каждой передаче.', 'bigtech_interview': '**Вопрос с собеседования:** «Как размер буфера каналов влияет на пропускную способность (throughput) и задержку (latency) конвейера?»\n**Ответ:** Увеличение буфера повышает Throughput (меньше системных переключений), но увеличивает Latency отдельных сообщений при всплесках нагрузки (Bufferbloat).'}, {'num': 17, 'title': 'Полный цикл Fan-Out / Fan-In: генератор, 4 воркера и синхронный мержер', 'task': 'Реализуй **Fan-Out / Fan-In**: один генератор, 4 воркера (fan-out), один мержер (fan-in). Воркеры обрабатывают задачи параллельно, результаты собираются в один канал. Используй `sync.WaitGroup` для fan-in.', 'theory': 'Каноническая архитектура Fan-Out/Fan-In: один поток задач разделяется на $M$ параллельных воркеров и затем собирается в единый упорядоченный или неупорядоченный результирующий поток.', 'step_by_step': '1. Создадим генератор чисел от 1 до 8.\n2. Создадим 4 параллельных воркера `heavyWorker(in)`.\n3. Объединим их выходы в `merge(channels...)`.\n4. Проверим расчет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc genData(nums ...int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor _, n := range nums {\n\t\t\tout <- n\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc computeNode(id int, in <-chan int) <-chan string {\n\tout := make(chan string)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t\tout <- fmt.Sprintf("[Worker #%d] %d^3 = %d", id, n, n*n*n)\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc mergeStreams(cs ...<-chan string) <-chan string {\n\tout := make(chan string)\n\tvar wg sync.WaitGroup\n\n\tfor _, c := range cs {\n\t\twg.Add(1)\n\t\tgo func(ch <-chan string) {\n\t\t\tdefer wg.Done()\n\t\t\tfor val := range ch {\n\t\t\t\tout <- val\n\t\t\t}\n\t\t}(c)\n\t}\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(out)\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tin := genData(1, 2, 3, 4, 5, 6, 7, 8)\n\n\t// Fan-Out: 4 параллельных воркера\n\tw1 := computeNode(1, in)\n\tw2 := computeNode(2, in)\n\tw3 := computeNode(3, in)\n\tw4 := computeNode(4, in)\n\n\t// Fan-In: слияние\n\tfor res := range mergeStreams(w1, w2, w3, w4) {\n\t\tfmt.Println(res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] 1^3 = 1\n# [Worker #2] 2^3 = 8\n# [Worker #3] 3^3 = 27\n# [Worker #4] 4^3 = 64\n# [Worker #1] 5^3 = 125\n# [Worker #2] 6^3 = 216\n# [Worker #3] 7^3 = 343\n# [Worker #4] 8^3 = 512'}], 'under_the_hood': 'Все 4 воркера вычитывают общий канал `in` с минимальным contention благодаря мьютексу в `hchan`.', 'pitfalls': 'Порядок вывода результатов в Fan-In не детерминирован из-за параллельного выполнения воркеров.', 'bigtech_interview': '**Вопрос с собеседования:** «Как гарантировать сохранение порядка элементов при использовании Fan-Out / Fan-In?»\n**Ответ:** Прикрепить к каждому элементу индекс `Job{Index: i, Value: val}` и на этапе слияния использовать реордеринг-буфер (min-heap или слайс с индексом ожидаемого элемента).'}, {'num': 18, 'title': 'Трехстадийный конвейер: Генерация (1..100) -> Нечетные -> Квадраты', 'task': '**Паттерн "Конвейер" (Pipeline)**: Напишите конвейер обработки чисел из трех стадий (каждая стадия — это функция, принимающая канал и возвращающая новый канал):\n    * Стадия 1: Генерация чисел от 1 до 100.\n    * Стадия 2: Фильтрация (пропускает только нечетные числа).\n    * Стадия 3: Возведение в квадрат.\n    В функции `main` прочитайте финальные результаты из выходного канала.', 'theory': 'Практика функциональной декомпозиции конвейера: каждая стадия оформлена отдельной чистой функцией, принимающей и возвращающей канал.', 'step_by_step': '1. Реализуем `stageGenerate(max int) <-chan int`.\n2. Реализуем `stageFilterOdd(in <-chan int) <-chan int`.\n3. Реализуем `stageSquare(in <-chan int) <-chan int`.\n4. Выведем первые 5 результатов в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\n// Стадия 1: Генерация чисел 1..100\nfunc stageGenerate(max int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor i := 1; i <= max; i++ {\n\t\t\tout <- i\n\t\t}\n\t}()\n\treturn out\n}\n\n// Стадия 2: Фильтрация нечетных чисел\nfunc stageFilterOdd(in <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tif n%2 != 0 {\n\t\t\t\tout <- n\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\n// Стадия 3: Возведение в квадрат\nfunc stageSquare(in <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tout <- n * n\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc main() {\n\t// Композиция конвейера\n\tpipeline := stageSquare(stageFilterOdd(stageGenerate(10)))\n\n\tfmt.Println("Квадраты нечетных чисел от 1 до 10:")\n\tfor res := range pipeline {\n\t\tfmt.Printf(" -> %d\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Квадраты нечетных чисел от 1 до 10:\n#  -> 1\n#  -> 9\n#  -> 25\n#  -> 49\n#  -> 81'}], 'under_the_hood': 'Каждая стадия закрывает свой выходной канал, запуская каскадное завершение цикла `for range` следующей стадии.', 'pitfalls': 'Пропуск `defer close(out)` на любой стадии заморозит конвейер навсегда.', 'bigtech_interview': '**Вопрос с собеседования:** «Как обработать ошибки, возникающие внутри промежуточных стадий Pipeline?»\n**Ответ:** Передавать через канал структуры-результаты `Result[T]{ Value T, Err error }` либо передавать выделенный канал ошибок `errc <-chan error`.'}, {'num': 19, 'title': 'Паттерн Future / Promise: асинхронное вычисление и ленивое получение результата', 'task': 'Реализуй **Future / Promise**: функция `AsyncCompute(fn func() int) <-chan int` запускает `fn` в горутине и возвращает канал с результатом. Вызывающий читает из канала, когда результат нужен.', 'theory': 'Паттерн Future (или Promise) представляет собой дескриптор отложенного результата. Вызывающий поток инициирует тяжелое вычисление, продолжает выполнять другую полезную работу параллельно, а затем блокируется на чтении из канала `<-future` строго в момент, когда результат становится необходим.', 'step_by_step': '1. Создадим функцию `AsyncCompute[T any](fn func() T) <-chan T`.\n2. Запустим вычисление двух тяжелых независимых значений.\n3. Выполним параллельную работу в `main`.\n4. Прочитаем результаты из обоих Future.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\n// AsyncCompute возвращает Future (канал с единственным результатом)\nfunc AsyncCompute[T any](fn func() T) <-chan T {\n\tpromise := make(chan T, 1) // Буфер = 1 для исключения блокировки\n\tgo func() {\n\t\tdefer close(promise)\n\t\tpromise <- fn()\n\t}()\n\treturn promise\n}\n\nfunc main() {\n\tstart := time.Now()\n\n\t// Запуск двух долгих фоновых вычислений параллельно\n\tfutureUserBalance := AsyncCompute(func() int {\n\t\ttime.Sleep(30 * time.Millisecond) // Запрос к Billing API\n\t\treturn 15000\n\t})\n\n\tfutureUserOrdersCount := AsyncCompute(func() int {\n\t\ttime.Sleep(30 * time.Millisecond) // Запрос к Orders DB\n\t\treturn 42\n\t})\n\n\t// Полезная работа в главном потоке\n\tfmt.Println("[Main] Главный поток выполняет подготовку шаблона...")\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Получение результатов (Awaiting Future)\n\tbalance := <-futureUserBalance\n\torders := <-futureUserOrdersCount\n\n\tfmt.Printf("[Main] Данные получены за %v: Баланс = %d руб., Заказов = %d\\n", \n\t\ttime.Since(start).Round(time.Millisecond), balance, orders)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Главный поток выполняет подготовку шаблона...\n# [Main] Данные получены за 30ms: Баланс = 15000 руб., Заказов = 42'}], 'under_the_hood': 'Оба запроса выполняются параллельно на разных горутинах, поэтому суммарное время ожидания равно $\\max(T_1, T_2) = 30$ мс вместо последовательных $60$ мс.', 'pitfalls': 'Всегда используйте `make(chan T, 1)` для Future, чтобы горутина не зависала, если вызывающий код решит проигнорировать результат.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем Future в Go отличается от java.util.concurrent.Future или JavaScript Promise?»\n**Ответ:** В Go нет необходимости в отдельном классе `Future`, так как однонаправленный буферизованный канал `<-chan T` нативно выполняет роль Future со встроенной поддержкой таймаутов через `select`.'}, {'num': 20, 'title': 'Реализация пользовательского семафора Semaphore: Acquire и Release', 'task': 'Реализуй **Semaphore** через канал: `type Semaphore chan struct{}`. Методы: `Acquire()`, `Release()`. Ограничь доступ к ресурсу (например, 2 одновременных запроса к "базе данных").', 'theory': 'Инкапсуляция канального семафора в отдельный тип `Semaphore` с методами `Acquire()` и `Release()` создает чистый и понятный API.', 'step_by_step': '1. Объявим тип `type Semaphore chan struct{}`.\n2. Реализуем конструктор `NewSemaphore(n int)`.\n3. Реализуем методы `Acquire()` и `Release()`.\n4. Ограничим параллельный доступ к ресурсу 2 потоками.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Semaphore chan struct{}\n\nfunc NewSemaphore(limit int) Semaphore {\n\treturn make(Semaphore, limit)\n}\n\nfunc (s Semaphore) Acquire() {\n\ts <- struct{}{}\n}\n\nfunc (s Semaphore) Release() {\n\t<-s\n}\n\nfunc accessDatabase(id int, sem Semaphore, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\tsem.Acquire()\n\tdefer sem.Release()\n\n\tfmt.Printf("[DB-Client #%d] Подключение активно...\\n", id)\n\ttime.Sleep(15 * time.Millisecond)\n\tfmt.Printf(" -> [DB-Client #%d] Подключение закрыто\\n", id)\n}\n\nfunc main() {\n\tsem := NewSemaphore(2) // Максимум 2 одновременных горутины\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= 4; i++ {\n\t\twg.Add(1)\n\t\tgo accessDatabase(i, sem, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все запросы обработаны через Semaphore.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [DB-Client #1] Подключение активно...\n# [DB-Client #2] Подключение активно...\n#  -> [DB-Client #1] Подключение закрыто\n#  -> [DB-Client #2] Подключение закрыто\n# [DB-Client #3] Подключение активно...\n# [DB-Client #4] Подключение активно...\n#  -> [DB-Client #3] Подключение закрыто\n#  -> [DB-Client #4] Подключение закрыто\n# [Main] Все запросы обработаны через Semaphore.'}], 'under_the_hood': 'Вызов `Acquire()` блокирует горутину при заполненном буфере, а `Release()` переводит ожидающую горутину в состояние `_Grunnable`.', 'pitfalls': 'Забытый `defer sem.Release()` приведет к перманентной потере слотов семафора и зависанию программы.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда стоит использовать golang.org/x/sync/semaphore вместо семафора на каналах?»\n**Ответ:** Когда требуется взвешенный семафор (Weighted Semaphore), позволяющий захватывать не 1 слот, а сразу $K$ слотов под тяжелую операцию (`Acquire(ctx, 5)`), а также поддерживать отмену по `context.Context`.'}, {'num': 21, 'title': 'Паттерн Rate Limiter: алгоритм Token Bucket на буферизованном канале', 'task': 'Реализуй **Rate Limiter** (token bucket): канал `tokens` с буфером N. Каждый запрос берёт токен (`<-tokens`). Пополняющая горутина добавляет токен каждые `interval`. Если токенов нет — запрос блокируется.', 'theory': 'Алгоритм Token Bucket: в корзину фиксированной емкости с постоянной скоростью поступают токены. Запрос может выполниться только при наличии токена в корзине. Допускает кратковременные всплески трафика (Burst) в пределах емкости корзины.', 'step_by_step': '1. Создадим структуру `TokenBucketRateLimiter`.\n2. Запустим тикер, пополняющий канал токенами `select { case tokens <- struct{}{}: default: }`.\n3. Реализуем метод `Wait()`.\n4. Продемонстрируем плавный пропуск 5 запросов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\ntype TokenBucket struct {\n\ttokens chan struct{}\n\tstop   chan struct{}\n}\n\nfunc NewTokenBucket(capacity int, refillRate time.Duration) *TokenBucket {\n\ttb := &TokenBucket{\n\t\ttokens: make(chan struct{}, capacity),\n\t\tstop:   make(chan struct{}),\n\t}\n\n\t// Изначально корзина полная (Burst capacity)\n\tfor i := 0; i < capacity; i++ {\n\t\ttb.tokens <- struct{}{}\n\t}\n\n\t// Фоновое пополнение токенов\n\tgo func() {\n\t\tticker := time.NewTicker(refillRate)\n\t\tdefer ticker.Stop()\n\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-tb.stop:\n\t\t\t\treturn\n\t\t\tcase <-ticker.C:\n\t\t\t\tselect {\n\t\t\t\tcase tb.tokens <- struct{}{}:\n\t\t\t\tdefault: // Корзина полная -> токен сгорает\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn tb\n}\n\nfunc (tb *TokenBucket) Take() {\n\t<-tb.tokens // Блокируется, если токенов нет\n}\n\nfunc (tb *TokenBucket) Close() {\n\tclose(tb.stop)\n}\n\nfunc main() {\n\tlimiter := NewTokenBucket(2, 20*time.Millisecond)\n\tdefer limiter.Close()\n\n\tstart := time.Now()\n\tfor req := 1; req <= 5; req++ {\n\t\tlimiter.Take()\n\t\tfmt.Printf("[RateLimiter] Запрос #%d пропущен в %v\\n", \n\t\t\treq, time.Since(start).Round(time.Millisecond))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [RateLimiter] Запрос #1 пропущен в 0s\n# [RateLimiter] Запрос #2 пропущен в 0s\n# [RateLimiter] Запрос #3 пропущен в 20ms\n# [RateLimiter] Запрос #4 пропущен в 40ms\n# [RateLimiter] Запрос #5 пропущен в 60ms'}], 'under_the_hood': 'Первые 2 запроса выполняются мгновенно за счет начального burst-буфера, а последующие строго с интервалом в 20 мс.', 'pitfalls': 'Не забывайте закрывать тикер через канал остановки `tb.stop` для предотвращения утечки фоновой горутины.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы преимущества Token Bucket перед Leaky Bucket?»\n**Ответ:** Token Bucket разрешает мгновенную обработку всплесков трафика (Bursts) в пределах емкости корзины, тогда как Leaky Bucket строго сглаживает весь трафик до постоянной скорости.'}, {'num': 22, 'title': 'Классический Worker Pool: jobs, results и конкурентная обработка', 'task': '**Паттерн "Worker Pool" (Пул воркеров)**: Напишите классический пул воркеров. У вас есть канал задач `jobs` и канал результатов `results`. Запустите фиксированное количество горутин-воркеров (например, 3 воркера), которые разбирают задачи из канала `jobs`, имитируют работу и отправляют результаты в канал `results`.', 'theory': 'Каноническая реализация пула воркеров с разделением очередей задач и результатов.', 'step_by_step': '1. Создадим канал `jobs := make(chan int, 100)`.\n2. Создадим канал `results := make(chan int, 100)`.\n3. Запустим 3 воркера, читающих `jobs`.\n4. Отправим 5 задач, соберем 5 результатов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc worker(id int, jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor j := range jobs {\n\t\tfmt.Printf("[Worker #%d] Обработка задачи: %d\\n", id, j)\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tresults <- j * 2\n\t}\n}\n\nfunc main() {\n\tconst numJobs = 5\n\tjobs := make(chan int, numJobs)\n\tresults := make(chan int, numJobs)\n\tvar wg sync.WaitGroup\n\n\t// Запуск 3 воркеров\n\tfor w := 1; w <= 3; w++ {\n\t\twg.Add(1)\n\t\tgo worker(w, jobs, results, &wg)\n\t}\n\n\t// Отправка задач\n\tfor j := 1; j <= numJobs; j++ {\n\t\tjobs <- j\n\t}\n\tclose(jobs)\n\n\t// Закрываем results после завершения всех воркеров\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\t// Вычитываем все результаты\n\tfor res := range results {\n\t\tfmt.Printf("Получен результат: %d\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Обработка задачи: 1\n# [Worker #2] Обработка задачи: 2\n# [Worker #3] Обработка задачи: 3\n# [Worker #1] Обработка задачи: 4\n# [Worker #2] Обработка задачи: 5\n# Получен результат: 2\n# Получен результат: 4\n# Получен результат: 6\n# Получен результат: 8\n# Получен результат: 10'}], 'under_the_hood': '`close(jobs)` оповещает всех 3 воркеров об окончании задач, после чего они выходят из цикла `for range jobs`.', 'pitfalls': 'Если забыть закрыть `results`, цикл чтения `for res := range results` зависнет в дедлоке.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go не используют динамический пул потоков (как в Java ThreadPoolExecutor)?»\n**Ответ:** Горутины в Go сверхлегкие (2 КБ стека против 1 МБ у потока ОС), поэтому запуск 1000 горутин не перегружает ОС. Фиксированный пул воркеров в Go создают не ради экономии памяти, а для защиты внешних ресурсов (БД, сетевые сокеты).'}, {'num': 23, 'title': 'Паттерн Rate Limiter: алгоритм Leaky Bucket с отбрасыванием избыточных запросов', 'task': 'Реализуй **Rate Limiter** (leaky bucket): запросы поступают в буферизованный канал. Обрабатывающая горутина читает из канала с фиксированной частотой (`time.Ticker`). Если буфер переполнен — запрос отклоняется.', 'theory': 'Алгоритм Leaky Bucket (Протекающее ведро): запросы сбрасываются в буфер фиксированного размера. Если буфер полон — свежие запросы немедленно отклоняются со статусом HTTP 429 Too Many Requests. Обработчик вытекает с постоянной фиксированной скоростью.', 'step_by_step': '1. Создадим структуру `LeakyBucket` с буферизованным каналом емкостью 2.\n2. Реализуем метод `Push(requestID int) bool` через `select default`.\n3. Запустим фоновую горутину, вычитывающую запросы по тикеру.\n4. Отправим серию запросов и проверим отбрасывание избыточных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\ntype LeakyBucket struct {\n\tqueue chan int\n\tstop  chan struct{}\n}\n\nfunc NewLeakyBucket(capacity int, leakInterval time.Duration) *LeakyBucket {\n\tlb := &LeakyBucket{\n\t\tqueue: make(chan int, capacity),\n\t\tstop:  make(chan struct{}),\n\t}\n\n\tgo func() {\n\t\tticker := time.NewTicker(leakInterval)\n\t\tdefer ticker.Stop()\n\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-lb.stop:\n\t\t\t\treturn\n\t\t\tcase <-ticker.C:\n\t\t\t\tselect {\n\t\t\t\tcase req := <-lb.queue:\n\t\t\t\t\tfmt.Printf("[LeakyBucket Leak] Обработан запрос #%d (Очередь: %d/%d)\\n", \n\t\t\t\t\t\treq, len(lb.queue), capacity)\n\t\t\t\tdefault:\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn lb\n}\n\nfunc (lb *LeakyBucket) Submit(reqID int) bool {\n\tselect {\n\tcase lb.queue <- reqID:\n\t\tfmt.Printf("[LeakyBucket] Запрос #%d принят в очередь\\n", reqID)\n\t\treturn true\n\tdefault:\n\t\tfmt.Printf("[LeakyBucket DROP] Буфер переполнен! Запрос #%d отклонен (HTTP 429)\\n", reqID)\n\t\treturn false\n\t}\n}\n\nfunc (lb *LeakyBucket) Close() {\n\tclose(lb.stop)\n}\n\nfunc main() {\n\tlb := NewLeakyBucket(2, 25*time.Millisecond)\n\tdefer lb.Close()\n\n\t// Отправляем 4 запроса подряд\n\tfor i := 1; i <= 4; i++ {\n\t\tlb.Submit(i)\n\t}\n\n\ttime.Sleep(100 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [LeakyBucket] Запрос #1 принят в очередь\n# [LeakyBucket] Запрос #2 принят в очередь\n# [LeakyBucket DROP] Буфер переполнен! Запрос #3 отклонен (HTTP 429)\n# [LeakyBucket DROP] Буфер переполнен! Запрос #4 отклонен (HTTP 429)\n# [LeakyBucket Leak] Обработан запрос #1 (Очередь: 1/2)\n# [LeakyBucket Leak] Обработан запрос #2 (Очередь: 0/2)'}], 'under_the_hood': '`select default` обеспечивает неблокирующую отправку за 0 аллокаций.', 'pitfalls': 'Отказ от `select default` приведет к блокировке HTTP-хендлера при заполнении очереди.', 'bigtech_interview': '**Вопрос с собеседования:** «В каких случаях выбирают Leaky Bucket вместо Token Bucket?»\n**Ответ:** Когда целевой сервис (например, legacy-база данных) не выдерживает даже кратковременных всплесков трафика и требует строго постоянного и равномерного потока запросов без скачков RPS.'}, {'num': 24, 'title': 'Воспроизведение и анатомия взаимной блокировки (Deadlock) с флагом -race', 'task': 'Deadlock: создайте ситуацию взаимной блокировки (две горутины, два мьютекса, захватываемых в разном порядке). Обнаружьте с `-race`.', 'theory': 'Взаимная блокировка (Deadlock) возникает при несоблюдении порядка захвата ресурсов (Circular Wait):\n* Горутина 1 захватывает Lock A и ждет Lock B.\n* Горутина 2 захватывает Lock B и ждет Lock A.\nОбе горутины блокируются навсегда.', 'step_by_step': '1. Создадим два мьютекса `muA` и `muB`.\n2. Запустим горутину 1: `Lock(A) -> Sleep -> Lock(B)`.\n3. Запустим горутину 2: `Lock(B) -> Sleep -> Lock(A)`.\n4. Продемонстрируем детектирование взаимной блокировки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Account struct {\n\tid      int\n\tbalance int\n\tmu      sync.Mutex\n}\n\n// Ошибочная функция перевода с нарушением порядка захвата мьютексов\nfunc transferDeadlock(from, to *Account, amount int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\tfrom.mu.Lock()\n\tfmt.Printf("[Transfer] Захвачен мьютекс счета #%d, ожидание счета #%d...\\n", from.id, to.id)\n\ttime.Sleep(10 * time.Millisecond)\n\n\tto.mu.Lock() // DEADLOCK, если встречный перевод захватил to.mu!\n\tfrom.balance -= amount\n\tto.balance += amount\n\tto.mu.Unlock()\n\tfrom.mu.Unlock()\n}\n\nfunc main() {\n\tacc1 := &Account{id: 1, balance: 1000}\n\tacc2 := &Account{id: 2, balance: 2000}\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\t// Встречные переводы с перекрестным порядком блокировки\n\tgo transferDeadlock(acc1, acc2, 100, &wg)\n\tgo transferDeadlock(acc2, acc1, 200, &wg)\n\n\t// Ждем 50 мс для демонстрации дедлока\n\ttime.Sleep(50 * time.Millisecond)\n\tfmt.Println("\\n[Main] ОБНАРУЖЕН DEADLOCK: Обе горутины заблокированы навсегда в ожидании встречных мьютексов!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Transfer] Захвачен мьютекс счета #1, ожидание счета #2...\n# [Transfer] Захвачен мьютекс счета #2, ожидание счета #1...\n# \n# [Main] ОБНАРУЖЕН DEADLOCK: Обе горутины заблокированы навсегда в ожидании встречных мьютексов!'}], 'under_the_hood': 'Если все горутины в программе заснут на мьютексах или каналах, рантайм Go выбросит фатальную панику `fatal error: all goroutines are asleep - deadlock!`.', 'pitfalls': 'Флаг `-race` детектирует Data Races, но дедлоки выявляются анализом порядка блокировок или профилировщиком блокировок (`pprof/block`).', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы 4 условия возникновения дедлока Коффмана (Coffman Conditions)?»\n**Ответ:** 1) Mutual Exclusion (взаимоисключение), 2) Hold and Wait (удержание и ожидание), 3) No Preemption (невозможность отбора ресурса), 4) Circular Wait (круговое ожидание). Нарушение любого из 4 условий полностью исключает дедлок.'}, {'num': 25, 'title': 'Многотопиковый брокер сообщений Pub/Sub с RWMutex и топиками', 'task': 'Реализуй **Pub/Sub** через каналы: `type PubSub struct { subscribers map[string][]chan string; mu sync.RWMutex }`. Методы: `Subscribe(topic string) <-chan string`, `Publish(topic, msg string)`. Подписчики получают сообщения.', 'theory': 'Многотопиковый брокер (Multi-Topic PubSub): подписчики подписываются на конкретные темы (например, `"orders"` или `"metrics"`). Издатель публикует сообщения в топик, а брокер маршрутизирует их только заинтересованным клиентам.', 'step_by_step': '1. Создадим структуру `PubSub` с мапой подписчиков по топикам.\n2. Реализуем `Subscribe(topic string) <-chan string`.\n3. Реализуем `Publish(topic, msg string)`.\n4. Продемонстрируем изоляцию сообщений между топиками.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype PubSub struct {\n\tmu          sync.RWMutex\n\tsubscribers map[string][]chan string\n}\n\nfunc NewPubSub() *PubSub {\n\treturn &PubSub{\n\t\tsubscribers: make(map[string][]chan string),\n\t}\n}\n\nfunc (ps *PubSub) Subscribe(topic string) <-chan string {\n\tps.mu.Lock()\n\tdefer ps.mu.Unlock()\n\n\tch := make(chan string, 5)\n\tps.subscribers[topic] = append(ps.subscribers[topic], ch)\n\treturn ch\n}\n\nfunc (ps *PubSub) Publish(topic, msg string) {\n\tps.mu.RLock()\n\tdefer ps.mu.RUnlock()\n\n\tfor _, ch := range ps.subscribers[topic] {\n\t\tselect {\n\t\tcase ch <- msg:\n\t\tdefault:\n\t\t}\n\t}\n}\n\nfunc main() {\n\tps := NewPubSub()\n\n\tordersChan := ps.Subscribe("orders")\n\tmetricsChan := ps.Subscribe("metrics")\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfmt.Printf("[Orders-Service] %s\\n", <-ordersChan)\n\t}()\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfmt.Printf("[Metrics-Service] %s\\n", <-metricsChan)\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tps.Publish("orders", "Создан заказ #9872")\n\tps.Publish("metrics", "CPU Usage = 42%")\n\n\twg.Wait()\n\tfmt.Println("[Main] Маршрутизация сообщений по топикам выполнена успешно.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Orders-Service] Создан заказ #9872\n# [Metrics-Service] CPU Usage = 42%\n# [Main] Маршрутизация сообщений по топикам выполнена успешно.'}], 'under_the_hood': '`sync.RWMutex` позволяет десяткам параллельных издателей вызывать `Publish` одновременно (`RLock`), блокируя только при добавлении нового подписчика (`Lock`).', 'pitfalls': 'Обязательно проверяйте наличие топика в мапе `subscribers[topic]`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать Unsubscribe для удаления одного конкретного канала из топика?»\n**Ответ:** Захватить `ps.mu.Lock()`, найти канал в срезе `subscribers[topic]`, удалить его быстрым сдвигом `s = append(s[:i], s[i+1:]...)` и закрыть удаленный канал `close(ch)`.'}, {'num': 26, 'title': 'Идиоматичный паттерн Fan-In со строгой синхронизацией sync.WaitGroup', 'task': '**Паттерн "Fan-In" (Слияние каналов)**: Напишите функцию `FanIn(channels ...<-chan int) <-chan int`. Она должна принимать произвольное количество каналов, запускать горутины для чтения из каждого и сливать все полученные данные в один результирующий канал. Обеспечьте корректное закрытие результирующего канала только после того, как закроются ВСЕ входные каналы (используйте `sync.WaitGroup`).', 'theory': 'Строгий протокол закрытия в Fan-In: результирующий канал должен закрываться **строго один раз** и только после того, как все входные каналы полностью закрылись и вычитаны.', 'step_by_step': '1. Создадим `FanIn(channels ...<-chan int) <-chan int`.\n2. Запустим горутины считывания с `defer wg.Done()`.\n3. В горутине ожидания вызовем `wg.Wait()` и `close(out)`.\n4. Проверим слияние 3 числовых каналов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc FanIn(channels ...<-chan int) <-chan int {\n\tout := make(chan int)\n\tvar wg sync.WaitGroup\n\n\t// Функция считывания для каждого отдельного канала\n\tmultiplex := func(c <-chan int) {\n\t\tdefer wg.Done()\n\t\tfor val := range c {\n\t\t\tout <- val\n\t\t}\n\t}\n\n\twg.Add(len(channels))\n\tfor _, ch := range channels {\n\t\tgo multiplex(ch)\n\t}\n\n\t// Гарантированное закрытие out после завершения всех горутин\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(out)\n\t}()\n\n\treturn out\n}\n\nfunc gen(nums ...int) <-chan int {\n\tch := make(chan int)\n\tgo func() {\n\t\tdefer close(ch)\n\t\tfor _, n := range nums {\n\t\t\tch <- n\n\t\t}\n\t}()\n\treturn ch\n}\n\nfunc main() {\n\tc1 := gen(10, 20)\n\tc2 := gen(30, 40)\n\tc3 := gen(50, 60)\n\n\tmerged := FanIn(c1, c2, c3)\n\n\tsum := 0\n\tfor num := range merged {\n\t\tsum += num\n\t\tfmt.Printf("Получено число: %d\\n", num)\n\t}\n\n\tfmt.Printf("Итоговая сумма всех элементов: %d\\n", sum)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено число: 10\n# Получено число: 20\n# Получено число: 30\n# Получено число: 40\n# Получено число: 50\n# Получено число: 60\n# Итоговая сумма всех элементов: 210'}], 'under_the_hood': '`wg.Wait()` ждет завершения всех `len(channels)` горутин, предотвращая утечки и раннее закрытие.', 'pitfalls': 'Вызов `close(out)` внутри горутины `multiplex` вызвал бы панику при повторном закрытии остальными горутинами.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему Fan-In не гарантирует упорядоченность элементов?»\n**Ответ:** Потому что горутины вычитывают данные конкурентно и соревнуются за запись в общий канал `out`. Порядок записи определяется планировщиком Go.'}, {'num': 27, 'title': 'Синхронизированная ограниченная очередь Bounded Queue на каналах', 'task': 'Реализуй **Bounded Queue** через канал: `type Queue struct { ch chan int }`. Методы `Enqueue(v int) bool` (false если полон), `Dequeue() (int, bool)`. Используй канал как синхронизированную очередь.', 'theory': 'Буферизованный канал Go — это готовая lock-free кольцевая очередь FIFO. Методы `Enqueue` и `Dequeue` с использованием `select default` позволяют реализовать неблокирующую очередь.', 'step_by_step': '1. Создадим структуру `Queue struct { ch chan int }`.\n2. Реализуем `Enqueue(v int) bool` с `select default`.\n3. Реализуем `Dequeue() (int, bool)` с `select default`.\n4. Протестируем поведение при переполнении и опустошении.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\ntype Queue struct {\n\tch chan int\n}\n\nfunc NewQueue(capacity int) *Queue {\n\treturn &Queue{\n\t\tch: make(chan int, capacity),\n\t}\n}\n\nfunc (q *Queue) Enqueue(v int) bool {\n\tselect {\n\tcase q.ch <- v:\n\t\treturn true\n\tdefault:\n\t\treturn false // Очередь переполнена\n\t}\n}\n\nfunc (q *Queue) Dequeue() (int, bool) {\n\tselect {\n\tcase val := <-q.ch:\n\t\treturn val, true\n\tdefault:\n\t\treturn 0, false // Очередь пуста\n\t}\n}\n\nfunc main() {\n\tq := NewQueue(2)\n\n\tfmt.Println("Enqueue 10:", q.Enqueue(10)) // true\n\tfmt.Println("Enqueue 20:", q.Enqueue(20)) // true\n\tfmt.Println("Enqueue 30:", q.Enqueue(30)) // false (полна!)\n\n\tval, ok := q.Dequeue()\n\tfmt.Printf("Dequeue: val=%d, ok=%v\\n", val, ok)\n\n\tfmt.Println("Enqueue 30 (повторно):", q.Enqueue(30)) // true\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Enqueue 10: true\n# Enqueue 20: true\n# Enqueue 30: false\n# Dequeue: val=10, ok=true\n# Enqueue 30 (повторно): true'}], 'under_the_hood': '`select default` возвращает управление за пару процессорных инструкций без блокировки горутины в планировщике.', 'pitfalls': 'Для блокирующих версий методов достаточно убрать секцию `default`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова сложность операций Enqueue и Dequeue в канале Go?»\n**Ответ:** $O(1)$ по времени и $O(1)$ по дополнительной памяти благодаря кольцевому буферу массива внутри структуры `hchan`.'}, {'num': 28, 'title': 'Базовый генератор последовательности чисел с однонаправленным каналом', 'task': '**Генератор (Generator)**: Напиши функцию, которая внутри себя создает канал, запускает горутину (которая пишет туда числа 1..10 и закрывает его) и возвращает этот канал (`<-chan int`).', 'theory': 'Шаблон фабрики потока данных: создание канала, инкапсулированная горутина-писатель и возврат `<-chan int`.', 'step_by_step': '1. Создадим функцию `CountGenerator(start, end int) <-chan int`.\n2. Внутри выделим канал `ch := make(chan int)`.\n3. В горутине запишем числа и вызовем `close(ch)`.\n4. В `main` прочитаем поток.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc CountGenerator(start, end int) <-chan int {\n\tch := make(chan int)\n\tgo func() {\n\t\tdefer close(ch)\n\t\tfor i := start; i <= end; i++ {\n\t\t\tch <- i\n\t\t}\n\t}()\n\treturn ch\n}\n\nfunc main() {\n\tstream := CountGenerator(1, 5)\n\n\tfor num := range stream {\n\t\tfmt.Printf("Получено число из генератора: %d\\n", num)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено число из генератора: 1\n# Получено число из генератора: 2\n# Получено число из генератора: 3\n# Получено число из генератора: 4\n# Получено число из генератора: 5'}], 'under_the_hood': 'Синтаксис возвращаемого типа `<-chan int` запрещает вызывающему коду ошибочно писать в канал или вызывать `close()`.', 'pitfalls': 'Никогда не возвращайте двунаправленный `chan int`, если вызывающий код должен только читать.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему генераторы в Go всегда возвращают receive-only канал <-chan T?»\n**Ответ:** Это часть принципа наименьших привилегий (Principle of Least Privilege): только владелец канала (горутина-создатель) имеет право писать в него и закрывать его.'}, {'num': 29, 'title': 'Устранение Deadlock: канонический порядок блокировок (Lock Ordering)', 'task': 'Избегайте deadlock с помощью упорядочивания захвата мьютексов или `sync.Map`.', 'theory': 'Паттерн Lock Ordering (Строгое упорядочивание мьютексов): если для операции требуется захватить несколько мьютексов, они **всегда должны захватываться в строго одинаковом порядке** (например, по возрастанию их уникальных ID). Это математически исключает возникновение Circular Wait.', 'step_by_step': '1. Создадим структуру счета с ID.\n2. В функции перевода отсортируем счета: сначала блокируем счет с меньшим ID, затем с большим.\n3. Запустим 1000 конкурентных встречных переводов.\n4. Убедимся в полном отсутствии дедлоков.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype BankAccount struct {\n\tid      int\n\tbalance int\n\tmu      sync.Mutex\n}\n\n// Безопасный перевод: мьютексы ВСЕГДА захватываются в порядке возрастания ID!\nfunc safeTransfer(from, to *BankAccount, amount int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\tfirst, second := from, to\n\tif first.id > second.id {\n\t\tfirst, second = to, from\n\t}\n\n\tfirst.mu.Lock()\n\tsecond.mu.Lock()\n\n\tfrom.balance -= amount\n\tto.balance += amount\n\n\tsecond.mu.Unlock()\n\tfirst.mu.Unlock()\n}\n\nfunc main() {\n\tacc1 := &BankAccount{id: 1, balance: 10000}\n\tacc2 := &BankAccount{id: 2, balance: 10000}\n\n\tvar wg sync.WaitGroup\n\tconst iterations = 500\n\n\twg.Add(iterations * 2)\n\tfor i := 0; i < iterations; i++ {\n\t\tgo safeTransfer(acc1, acc2, 10, &wg)\n\t\tgo safeTransfer(acc2, acc1, 10, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Баланс счета #1: %d руб.\\n", acc1.balance)\n\tfmt.Printf("Баланс счета #2: %d руб.\\n", acc2.balance)\n\tfmt.Println("[Main] 1000 встречных переводов успешно выполнены без единого Deadlock!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Баланс счета #1: 10000 руб.\n# Баланс счета #2: 10000 руб.\n# [Main] 1000 встречных переводов успешно выполнены без единого Deadlock!'}], 'under_the_hood': 'Строгая иерархия захвата ресурсов исключает циклическое ожидание в графе блокировок.', 'pitfalls': 'Захват мьютексов в случайном порядке — одна из самых коварных ошибок в продакшене.', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить дедлок, если порядок ресурсов неизвестен заранее?»\n**Ответ:** Отсортировать указатели или ID ресурсов перед захватом блокировок (как показано выше), либо использовать неблокирующий захват `mu.TryLock()` с откатом (Backoff).'}, {'num': 30, 'title': 'Паттерн Circuit Breaker: конечный автомат Closed, Open и Half-Open', 'task': 'Реализуй **Circuit Breaker** (упрощённый): три состояния — `Closed`, `Open`, `HalfOpen`. При N ошибок подряд — переход в `Open`. В `Open` — быстрый fail. Через таймаут — `HalfOpen`, где один запрос пробует пройти. Используй `sync/atomic` для состояния.', 'theory': 'Паттерн Circuit Breaker (Предохранитель) защищает распределенную систему от каскадных сбоев:\n1. `Closed` (Норма): запросы идут к сервису. При $N$ сбоях подряд переход в `Open`.\n2. `Open` (Сбой): запросы не отправляются, а сразу возвращают ошибку `ErrCircuitOpen` (Fast Fail).\n3. `Half-Open` (Проверка): по истечении таймаута один пробный запрос проверяет доступность сервиса.', 'step_by_step': '1. Объявим состояния `StateClosed`, `StateOpen`, `StateHalfOpen`.\n2. Реализуем метод `Execute(fn func() error) error` с защитой мьютексом.\n3. Сымитируем сбой удаленного сервиса.\n4. Продемонстрируем мгновенный Fast Fail в состоянии `Open`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype State int\n\nconst (\n\tStateClosed State = iota\n\tStateOpen\n\tStateHalfOpen\n)\n\nvar ErrCircuitOpen = errors.New("circuit breaker is OPEN: fast fail")\n\ntype CircuitBreaker struct {\n\tmu           sync.Mutex\n\tstate        State\n\tmaxFailures  int\n\tfailureCount int\n\ttimeout      time.Duration\n\tlastStateChange time.Time\n}\n\nfunc NewCircuitBreaker(maxFailures int, timeout time.Duration) *CircuitBreaker {\n\treturn &CircuitBreaker{\n\t\tstate:        StateClosed,\n\t\tmaxFailures:  maxFailures,\n\t\ttimeout:      timeout,\n\t\tlastStateChange: time.Now(),\n\t}\n}\n\nfunc (cb *CircuitBreaker) Execute(fn func() error) error {\n\tcb.mu.Lock()\n\n\t// Проверка перехода из Open в Half-Open по таймауту\n\tif cb.state == StateOpen && time.Since(cb.lastStateChange) > cb.timeout {\n\t\tcb.state = StateHalfOpen\n\t\tcb.lastStateChange = time.Now()\n\t\tfmt.Println("[CircuitBreaker] Переход в состояние: HALF-OPEN (Пробный запрос)")\n\t}\n\n\tif cb.state == StateOpen {\n\t\tcb.mu.Unlock()\n\t\treturn ErrCircuitOpen // Мгновенный сброс без обращения к упавшему сервису\n\t}\n\n\tcb.mu.Unlock()\n\n\t// Выполняем операцию\n\terr := fn()\n\n\tcb.mu.Lock()\n\tdefer cb.mu.Unlock()\n\n\tif err != nil {\n\t\tcb.failureCount++\n\t\tif cb.failureCount >= cb.maxFailures || cb.state == StateHalfOpen {\n\t\t\tcb.state = StateOpen\n\t\t\tcb.lastStateChange = time.Now()\n\t\t\tfmt.Printf("[CircuitBreaker] Порог ошибок (%d) достигнут -> OPEN!\\n", cb.failureCount)\n\t\t}\n\t\treturn err\n\t}\n\n\t// Успех -> Сброс в Closed\n\tcb.failureCount = 0\n\tcb.state = StateClosed\n\treturn nil\n}\n\nfunc main() {\n\tcb := NewCircuitBreaker(2, 30*time.Millisecond)\n\n\tfailingService := func() error {\n\t\treturn errors.New("500 Internal Server Error")\n\t}\n\n\tfmt.Println("--- 1. Серия запросов к падающему сервису ---")\n\tfor i := 1; i <= 4; i++ {\n\t\terr := cb.Execute(failingService)\n\t\tfmt.Printf("Запрос #%d: %v\\n", i, err)\n\t}\n\n\tfmt.Println("\\n--- 2. Ожидание таймаута восстановления (Half-Open) ---")\n\ttime.Sleep(40 * time.Millisecond)\n\n\thealthyService := func() error {\n\t\tfmt.Println(" -> Удаленный сервис успешно восстановился!")\n\t\treturn nil\n\t}\n\terr := cb.Execute(healthyService)\n\tfmt.Printf("Пробный запрос: %v\\n", err)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- 1. Серия запросов к падающему сервису ---\n# Запрос #1: 500 Internal Server Error\n# [CircuitBreaker] Порог ошибок (2) достигнут -> OPEN!\n# Запрос #2: 500 Internal Server Error\n# Запрос #3: circuit breaker is OPEN: fast fail\n# Запрос #4: circuit breaker is OPEN: fast fail\n# \n# --- 2. Ожидание таймаута восстановления (Half-Open) ---\n# [CircuitBreaker] Переход в состояние: HALF-OPEN (Пробный запрос)\n#  -> Удаленный сервис успешно восстановился!\n# Пробный запрос: <nil>'}], 'under_the_hood': 'Состояние `Open` спасает сервис от лавинной перегрузки: запросы отсекаются за доли микросекунды на уровне клиента.', 'pitfalls': 'Слишком короткий таймаут `timeout` не даст упавшему сервису успеть перезагрузиться.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Circuit Breaker от Rate Limiter?»\n**Ответ:** Rate Limiter защищает *сервер* от перегрузки входящим трафиком (RPS limit). Circuit Breaker защищает *клиента* и нижележащие сервисы от бесполезных вызовов к уже упавшему серверу (Fast Failure).'}, {'num': 31, 'title': 'Сбор результатов из пула воркеров: 10 задач, 3 исполнителя', 'task': '**Пул воркеров (Worker Pool)**: Создай канал `jobs` и канал `results`. Запусти 3 горутины-воркера, которые читают из `jobs`, умножают число на 2 и пишут в `results`. Из `main` отправь 10 задач в `jobs` и собери 10 ответов.', 'theory': 'Практикум точной синхронизации: $N$ воркеров считывают фиксированное число задач и гарантированно возвращают ровно $K$ результатов.', 'step_by_step': '1. Создадим буферизованные каналы `jobs` и `results` на 10 элементов.\n2. Запустим 3 воркера с `sync.WaitGroup`.\n3. Отправим числа от 1 до 10.\n4. Вычитаем все 10 результатов в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc doubleWorker(id int, jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor j := range jobs {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tresults <- j * 2\n\t}\n}\n\nfunc main() {\n\tconst numTasks = 10\n\tjobs := make(chan int, numTasks)\n\tresults := make(chan int, numTasks)\n\tvar wg sync.WaitGroup\n\n\tfor w := 1; w <= 3; w++ {\n\t\twg.Add(1)\n\t\tgo doubleWorker(w, jobs, results, &wg)\n\t}\n\n\tfor i := 1; i <= numTasks; i++ {\n\t\tjobs <- i\n\t}\n\tclose(jobs)\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\tfmt.Println("Сбор ответов из пула:")\n\tfor res := range results {\n\t\tfmt.Printf(" -> Ответ: %d\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сбор ответов из пула:\n#  -> Ответ: 2\n#  -> Ответ: 4\n#  -> Ответ: 6\n#  -> Ответ: 8\n#  -> Ответ: 10\n#  -> Ответ: 12\n#  -> Ответ: 14\n#  -> Ответ: 16\n#  -> Ответ: 18\n#  -> Ответ: 20'}], 'under_the_hood': '`results` закрывается в фоновой горутине `go func() { wg.Wait(); close(results) }()`, что позволяет основному потоку сразу начать вычитывать результаты без дедлока.', 'pitfalls': 'Вызов `wg.Wait()` до чтения из `results` привел бы к взаимной блокировке при маленьком буфере.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему горутину закрытия канала результатов запускают до вычитывания из него?»\n**Ответ:** Это позволяет основному потоку и воркерам работать в конвейерном режиме: воркеры пишут, основной поток читает, а горутина ожидает финала и закрывает канал для выхода из `for range`.'}, {'num': 32, 'title': 'Паттерн Retry with Exponential Backoff и контекстной отменой', 'task': 'Реализуй **Retry with backoff**: функция пытается выполнить операцию 3 раза. Между попытками — экспоненциальная задержка (100ms, 200ms, 400ms). Если контекст отменён — прерывай сразу.', 'theory': 'Паттерн Retry with Exponential Backoff: повторные попытки с экспоненциально растущей паузой ($T \\cdot 2^{k}$) предотвращают перегрузку восстанавливающегося сервиса (Thundering Herd). Поддержка `context.Context` гарантирует мгновенную отмену при общем дедлайне запроса.', 'step_by_step': '1. Создадим функцию `RetryWithBackoff(ctx, maxAttempts, initialBackoff, op)`.\n2. В цикле выполняем операцию. При ошибке спим `backoff` через `select` с `ctx.Done()`.\n3. На каждой итерации удваиваем `backoff *= 2`.\n4. Проверим успешное восстановление на 3-й попытке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"time"\n)\n\nfunc RetryWithBackoff(ctx context.Context, maxRetries int, baseDelay time.Duration, fn func(attempt int) error) error {\n\tdelay := baseDelay\n\n\tfor attempt := 1; attempt <= maxRetries; attempt++ {\n\t\terr := fn(attempt)\n\t\tif err == nil {\n\t\t\treturn nil // Успех\n\t\t}\n\n\t\tif attempt == maxRetries {\n\t\t\treturn fmt.Errorf("исчерпаны все %d попыток: %w", maxRetries, err)\n\t\t}\n\n\t\tfmt.Printf("[Retry #%d] Ошибка: %v -> Пауза %v перед повтором...\\n", attempt, err, delay)\n\n\t\t// Прерываемая пауза\n\t\tselect {\n\t\tcase <-time.After(delay):\n\t\t\tdelay *= 2 // Экспоненциальное увеличение задержки\n\t\tcase <-ctx.Done():\n\t\t\treturn fmt.Errorf("повторные попытки прерваны контекстом: %w", ctx.Err())\n\t\t}\n\t}\n\n\treturn nil\n}\n\nfunc main() {\n\tctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)\n\tdefer cancel()\n\n\tunstableOperation := func(attempt int) error {\n\t\tif attempt < 3 {\n\t\t\treturn errors.New("503 Service Unavailable")\n\t\t}\n\t\tfmt.Println(" -> [Service] Запрос успешно обработан на попытке #3!")\n\t\treturn nil\n\t}\n\n\terr := RetryWithBackoff(ctx, 4, 15*time.Millisecond, unstableOperation)\n\tif err != nil {\n\t\tfmt.Printf("Финальная ошибка: %v\\n", err)\n\t} else {\n\t\tfmt.Println("[Main] Операция успешно завершилась благодаря Retry!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Retry #1] Ошибка: 503 Service Unavailable -> Пауза 15ms перед повтором...\n# [Retry #2] Ошибка: 503 Service Unavailable -> Пауза 30ms перед повтором...\n#  -> [Service] Запрос успешно обработан на попытке #3!\n# [Main] Операция успешно завершилась благодаря Retry!'}], 'under_the_hood': '`select` на `<-ctx.Done()` предотвращает бесполезные паузы, если у клиента уже истек общий таймаут.', 'pitfalls': 'В реальных распределенных системах к экспоненциальной задержке добавляют случайный шум (Jitter), чтобы запросы сотен клиентов не синхронизировались в фазе.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем к Exponential Backoff добавляют случайный Jitter?»\n**Ответ:** Без джиттера тысячи клиентов после сбоя сервера подождут ровно 100 мс и одновременно ударят по серверу новой волной запросов. Джиттер рандомизирует интервал ($[0.8 \\cdot T, 1.2 \\cdot T]$), равномерно распределяя нагрузку во времени.'}, {'num': 33, 'title': 'Паттерн Fan-Out с дублированием потока (Broadcast) всем слушателям', 'task': '**Паттерн "Fan-Out" (Раздача задач)**: Напишите программу, которая берет поток данных из одного канала и распределяет его по нескольким разным каналам-слушателям (каждое сообщение должно дублироваться во все каналы-слушатели).', 'theory': 'Паттерн Broadcast Fan-Out (Широковещательное разветвление): каждое входящее сообщение копируется во все выходные каналы-подписчики.', 'step_by_step': '1. Реализуем `Broadcast(in <-chan string, outs ...chan<- string)`.\n2. В цикле считываем `in` и дублируем сообщение во все `outs`.\n3. Подключим 3 приемника.\n4. Проверим доставку копий.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc Broadcast(in <-chan string, outputs ...chan<- string) {\n\tfor msg := range in {\n\t\tfor _, out := range outputs {\n\t\t\tout <- msg\n\t\t}\n\t}\n\tfor _, out := range outputs {\n\t\tclose(out)\n\t}\n}\n\nfunc main() {\n\tin := make(chan string, 5)\n\n\tout1 := make(chan string, 5)\n\tout2 := make(chan string, 5)\n\tout3 := make(chan string, 5)\n\n\tvar wg sync.WaitGroup\n\twg.Add(3)\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range out1 {\n\t\t\tfmt.Printf("[Audit-Service] %s\\n", msg)\n\t\t}\n\t}()\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range out2 {\n\t\t\tfmt.Printf("[Analytics-Service] %s\\n", msg)\n\t\t}\n\t}()\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range out3 {\n\t\t\tfmt.Printf("[Notification-Service] %s\\n", msg)\n\t\t}\n\t}()\n\n\t// Отправляем события в общий вход\n\tin <- "Event: UserRegistered"\n\tin <- "Event: OrderPaid"\n\tclose(in)\n\n\tBroadcast(in, out1, out2, out3)\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Audit-Service] Event: UserRegistered\n# [Audit-Service] Event: OrderPaid\n# [Analytics-Service] Event: UserRegistered\n# [Analytics-Service] Event: OrderPaid\n# [Notification-Service] Event: UserRegistered\n# [Notification-Service] Event: OrderPaid'}], 'under_the_hood': '`Broadcast` закрывает все выходные каналы после закрытия `in`.', 'pitfalls': 'Если один из выходных каналов забит, блокируется отправка и всем остальным подписчикам. Для решения используют буферы или `select default`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать Broadcast неблокирующим для медленных подписчиков?»\n**Ответ:** Использовать неблокирующую отправку `select default` с подсчетом отброшенных сообщений, либо оборачивать отправку каждому подписчику в отдельную горутину.'}, {'num': 34, 'title': 'Паттерн Parallel For: конкурентная обработка элементов с семафором', 'task': 'Реализуй **Parallel For** (аналог `Parallel.ForEach` в C#): `ParallelFor(items []int, fn func(int))`. Запускает обработку каждого элемента в горутине, но ограничивает concurrency через семафор.', 'theory': 'Паттерн Parallel For (Bounded Parallel Loop): параллельная обработка каждого элемента среза в отдельной горутине с ограничением числа одновременно выполняющихся горутин через семафор.', 'step_by_step': '1. Создадим `ParallelFor(items []int, maxConcurrency int, fn func(int))`.\n2. Запустим горутины с захватом семафора `sem <- struct{}{}`.\n3. Дождемся всех через `sync.WaitGroup`.\n4. Проверим параллельный расчет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc ParallelFor[T any](items []T, maxConcurrency int, fn func(item T)) {\n\tsem := make(chan struct{}, maxConcurrency)\n\tvar wg sync.WaitGroup\n\n\tfor _, item := range items {\n\t\twg.Add(1)\n\t\tsem <- struct{}{} // Захват слота\n\n\t\tgo func(val T) {\n\t\t\tdefer wg.Done()\n\t\t\tdefer func() { <-sem }() // Освобождение слота\n\t\t\tfn(val)\n\t\t}(item)\n\t}\n\n\twg.Wait()\n}\n\nfunc main() {\n\tnumbers := []int{10, 20, 30, 40, 50, 60}\n\n\tfmt.Println("Запуск ParallelFor с ограничением в 2 потока:")\n\tstart := time.Now()\n\n\tParallelFor(numbers, 2, func(n int) {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tfmt.Printf(" -> Обработан элемент: %d\\n", n)\n\t})\n\n\tfmt.Printf("Все элементы обработаны за %v!\\n", time.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запуск ParallelFor с ограничением в 2 потока:\n#  -> Обработан элемент: 10\n#  -> Обработан элемент: 20\n#  -> Обработан элемент: 30\n#  -> Обработан элемент: 40\n#  -> Обработан элемент: 50\n#  -> Обработан элемент: 60\n# Все элементы обработаны за 30ms!'}], 'under_the_hood': 'Захват слота `sem <- struct{}{}` происходит в главном цикле ДО запуска горутины, что предотвращает создание миллионов неактивных горутин в памяти.', 'pitfalls': 'Захват семафора внутри горутины `go func() { sem <- ... }` создаст миллион ожидающих горутин при большом срезе.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему sem <- struct{}{} нужно делать ДО вызова go func(), а не внутри нее?»\n**Ответ:** Это предотвращает неограниченный рост числа горутин (Goroutine Explosion) и защищает память от выделения тысяч стеков под заблокированные горутины.'}, {'num': 35, 'title': 'Детекция и ликвидация утечки горутин (Goroutine Leak) через runtime.NumGoroutine()', 'task': 'Утечка горутин: горутина пишет в канал, который никто не читает. Найдите утечку с помощью профилировщика или счётчика горутин (`runtime.NumGoroutine`). Исправьте, закрыв канал или добавив буфер/select.', 'theory': 'Утечка горутины (Goroutine Leak) — критический баг: горутина пытается отправить значение в небуферизованный канал, из которого никто не читает, и навсегда зависает в очереди `sendq`. Сборщик мусора Go (GC) **не может** освободить заблокированную горутину!', 'step_by_step': '1. Создадим функцию с утечкой (отправка в небуферизованный канал).\n2. Замерим `runtime.NumGoroutine()` и покажем зависшие горутины.\n3. Исправим утечку, добавив буфер `make(chan string, 1)`.\n4. Проверим нулевую утечку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"time"\n)\n\n// ИСПРАВЛЕННАЯ ФУНКЦИЯ: Буфер = 1 исключает утечку горутины!\nfunc queryFastestServerSafe() string {\n\tch := make(chan string, 1) // БУФЕР = 1\n\n\tgo func() {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tch <- "Ответ от Реплики 1" // Не заблокируется, даже если main уже ушел!\n\t}()\n\n\tgo func() {\n\t\ttime.Sleep(30 * time.Millisecond)\n\t\tch <- "Ответ от Реплики 2"\n\t}()\n\n\treturn <-ch // Читаем только самый быстрый ответ\n}\n\nfunc main() {\n\tfmt.Printf("1. Горутин до старта: %d\\n", runtime.NumGoroutine())\n\n\tfor i := 0; i < 5; i++ {\n\t\t_ = queryFastestServerSafe()\n\t}\n\n\ttime.Sleep(50 * time.Millisecond)\n\truntime.GC()\n\n\tfmt.Printf("2. Горутин после работы: %d (Утечки горутин полностью устранены!)\\n", runtime.NumGoroutine())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Горутин до старта: 1\n# 2. Горутин после работы: 1 (Утечки горутин полностью устранены!)'}], 'under_the_hood': 'Буферизованный канал позволяет второй медленной горутине положить свой запоздалый ответ в буфер и штатно освободить свой стек памяти.', 'pitfalls': 'В небуферизованном канале `make(chan string)` вторая горутина зависнет на вечность.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли сборщик мусора (GC) удалить зависшую горутину?»\n**Ответ:** Нет! Рантайм Go считает любую активную горутину корневым объектом трассировки (GC Root), поэтому вся ее память (стек, локальные переменные) остается в куче навсегда до завершения процесса.'}, {'num': 36, 'title': 'Data Race переменной цикла в замыкании (Loop Variable Shadowing)', 'task': '**Data Race с замыканием**: Запустите цикл `for`, в котором создаются горутины, использующие переменную цикла `i`. (Для Go < 1.22 все выведут последнее значение).', 'theory': 'До Go 1.22 переменная цикла `for i := 0; i < N; i++` переиспользовала один и тот же адрес памяти на всех итерациях. Анонимные горутины захватывали указатель на `i`, что приводило к Data Race и выводу одинаковых последних значений. В Go 1.22+ семантика цикла изменена на создание новой переменной на каждой итерации.', 'step_by_step': '1. Напишем цикл запуска горутин.\n2. Продемонстрируем передачу параметра `go func(val int)` как канонический кросс-версионный стандарт.\n3. Проверим вывод с флагом `-race`.\n4. Убедимся в корректности.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 5\n\n\twg.Add(total)\n\tfor i := 1; i <= total; i++ {\n\t\t// КАНОНИЧЕСКИЙ СПОСОБ: передача i параметром горутины гарантирует\n\t\t// независимую копию на стеке для ЛЮБОЙ версии Go (включая старые)!\n\t\tgo func(val int) {\n\t\t\tdefer wg.Done()\n\t\t\tfmt.Printf("Горутина получила значение: %d\\n", val)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все горутины вывели уникальные значения.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Горутина получила значение: 1\n# Горутина получила значение: 2\n# Горутина получила значение: 3\n# Горутина получила значение: 4\n# Горутина получила значение: 5\n# [Main] Все горутины вывели уникальные значения.'}], 'under_the_hood': 'Передача `val int` в аргументы создает локальную копию значения на фрейме стека созданной горутины.', 'pitfalls': 'Не полагайтесь на неявное поведение компилятора — явная передача параметров всегда предпочтительнее.', 'bigtech_interview': '**Вопрос с собеседования:** «Какое изменение в поведении цикла for произошло в релизе Go 1.22?»\n**Ответ:** Начиная с Go 1.22 переменные цикла `for i := range ...` имеют per-iteration область видимости (каждая итерация создает новую переменную в памяти), устраняя классический баг замыканий без флага GOEXPERIMENT=loopvar.'}, {'num': 37, 'title': 'Конкуренция 5 воркеров за задачи из единого канала генератора', 'task': '**Fan-out (Разветвление)**: Улучши упр. 308. Один "генератор" пишет задачи в канал, а 5 воркеров конкурируют за чтение из этого канала.', 'theory': 'Модель параллельной обработки: единый генератор непрерывно подает поток задач, а пул из 5 независимых воркеров автоматически распределяет их между ядрами.', 'step_by_step': '1. Создадим генератор 10 задач.\n2. Запустим 5 воркеров.\n3. Продемонстрируем равномерный разбор очереди.\n4. Дождемся завершения через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc taskGenerator(count int) <-chan int {\n\tout := make(chan int, count)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor i := 1; i <= count; i++ {\n\t\t\tout <- i\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc consumerWorker(id int, in <-chan int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor item := range in {\n\t\tfmt.Printf("[Worker #%d] Взял задачу: #%d\\n", id, item)\n\t\ttime.Sleep(10 * time.Millisecond)\n\t}\n}\n\nfunc main() {\n\ttasks := taskGenerator(10)\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 5\n\tfor w := 1; w <= numWorkers; w++ {\n\t\twg.Add(1)\n\t\tgo consumerWorker(w, tasks, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все 10 задач успешно разобраны 5 воркерами.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Взял задачу: #1\n# [Worker #2] Взял задачу: #2\n# [Worker #3] Взял задачу: #3\n# [Worker #4] Взял задачу: #4\n# [Worker #5] Взял задачу: #5\n# [Worker #1] Взял задачу: #6\n# [Worker #2] Взял задачу: #7\n# [Worker #3] Взял задачу: #8\n# [Worker #4] Взял задачу: #9\n# [Worker #5] Взял задачу: #10\n# [Main] Все 10 задач успешно разобраны 5 воркерами.'}], 'under_the_hood': 'Планировщик Go распределяет горутины по логическим процессорам $P$, обеспечивая параллельное исполнение.', 'pitfalls': 'Воркеры обязаны проверять закрытие канала через `for item := range in`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему 5 воркеров разбирают задачи из одного канала без необходимости мьютекса в коде пользователя?»\n**Ответ:** Потому что канал в Go (`runtime.hchan`) уже содержит встроенный мьютекс и потокобезопасную очередь ожидания, синхронизируя доступ горутин на уровне рантайма.'}, {'num': 38, 'title': 'Идентификация исполнителя: вывод уникального Worker ID при обработке', 'task': '**Fan-Out**: Создай один канал с задачами (числами). Запусти 3 горутины-обработчика (воркера), которые читают из этого канала и выводят результат с своим ID.', 'theory': 'Трассировка исполнителей: присвоение уникального ID каждой горутине пула позволяет анализировать балансировку нагрузки в логах.', 'step_by_step': '1. Создадим канал `tasks`.\n2. Запустим 3 воркера с ID 1, 2, 3.\n3. Отправим 6 чисел.\n4. Выведем результаты с привязкой к ID.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc runProcessor(workerID int, tasks <-chan int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor val := range tasks {\n\t\tfmt.Printf("[Worker #%d] Вычислен куб числа %d = %d\\n", workerID, val, val*val*val)\n\t\ttime.Sleep(5 * time.Millisecond)\n\t}\n}\n\nfunc main() {\n\ttasks := make(chan int, 6)\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= 3; i++ {\n\t\twg.Add(1)\n\t\tgo runProcessor(i, tasks, &wg)\n\t}\n\n\tfor n := 1; n <= 6; n++ {\n\t\ttasks <- n\n\t}\n\tclose(tasks)\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Вычислен куб числа 1 = 1\n# [Worker #2] Вычислен куб числа 2 = 8\n# [Worker #3] Вычислен куб числа 3 = 27\n# [Worker #1] Вычислен куб числа 4 = 64\n# [Worker #2] Вычислен куб числа 5 = 125\n# [Worker #3] Вычислен куб числа 6 = 216'}], 'under_the_hood': 'Каждый воркер работает в собственном стеке.', 'pitfalls': 'Не используйте глобальные переменные для ID воркеров.', 'bigtech_interview': '**Вопрос с собеседования:** «Как получить Goroutine ID в Go?»\n**Ответ:** В Go намеренно нет публичного API для получения Goroutine ID (в отличие от Java Thread ID), чтобы исключить использование антипаттерна `ThreadLocal`. Идентификатор передают явно через контекст или аргументы функций.'}, {'num': 39, 'title': 'Паттерн Map-Reduce на горутинах с барьером фаз sync.WaitGroup', 'task': 'Реализуй **Map-Reduce**: фаза Map — N горутин обрабатывают входные данные, фаза Reduce — одна горутина агрегирует результаты из канала. Используй `sync.WaitGroup` для барьера между фазами.', 'theory': 'Паттерн Map-Reduce в памяти:\n1. Фаза Map: $N$ параллельных горутин трансформируют исходные данные и пишут промежуточные результаты в канал.\n2. Барьер: `sync.WaitGroup` ожидает завершения всех Map-воркеров и закрывает канал.\n3. Фаза Reduce: терминальная горутина агрегирует (схлопывает) поток в итоговый результат.', 'step_by_step': '1. Подготовим срез слов.\n2. В фазе Map параллельно подсчитаем длины слов.\n3. Закроем промежуточный канал через барьер `wg.Wait()`.\n4. В фазе Reduce сложим суммарную длину всех слов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\twords := []string{"golang", "concurrency", "goroutine", "channel", "mutex", "pipeline"}\n\n\tmapChan := make(chan int, len(words))\n\tvar mapWg sync.WaitGroup\n\n\t// --- 1. ФАЗА MAP (Параллельная обработка) ---\n\tfor _, word := range words {\n\t\tmapWg.Add(1)\n\t\tgo func(w string) {\n\t\t\tdefer mapWg.Done()\n\t\t\tmapChan <- len(w) // Отображаем слово в его длину\n\t\t}(word)\n\t}\n\n\t// --- 2. БАРЬЕР МЕЖДУ ФАЗАМИ ---\n\tgo func() {\n\t\tmapWg.Wait()\n\t\tclose(mapChan)\n\t}()\n\n\t// --- 3. ФАЗА REDUCE (Агрегация результатов) ---\n\ttotalLength := 0\n\twordCount := 0\n\tfor length := range mapChan {\n\t\ttotalLength += length\n\t\twordCount++\n\t}\n\n\tavgLength := float64(totalLength) / float64(wordCount)\n\tfmt.Printf("Обработано слов: %d, Суммарная длина символов: %d\\n", wordCount, totalLength)\n\tfmt.Printf("Средняя длина слова: %.2f символов\\n", avgLength)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обработано слов: 6, Суммарная длина символов: 47\n# Средняя длина слова: 7.83 символов'}], 'under_the_hood': 'Барьерная горутина `go func() { mapWg.Wait(); close(mapChan) }()` развязывает фазы Map и Reduce без блокировки основного потока.', 'pitfalls': 'Запуск фазы Reduce до закрытия `mapChan` без барьера приведет к зависанию `for range`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как распределенный MapReduce (Hadoop, Spark) соотносится с Go-конкурентностью?»\n**Ответ:** Модель каналов и горутин в Go реализует те же принципы Map-Shuffle-Reduce в рамках одного сервера с использованием общей памяти и кольцевых очередей `hchan` вместо сетевых сокетов.'}, {'num': 40, 'title': 'Устранение Data Race при конкурентном append в общий срез', 'task': '**Data Race со слайсом**: Несколько горутин одновременно делают `append` в один общий слайс. Программа упадет с `concurrent map read and map write` или повредит память. Защитите слайс мьютексом.', 'theory': 'Срез (Slice) в Go состоит из трех полей `(array unsafe.Pointer, len int, cap int)`. Конкурентный вызов `append` из нескольких горутин без мьютекса приводит к повреждению памяти (Memory Corruption), перезаписи указателей на массив и потере элементов.', 'step_by_step': '1. Создадим структуру `SafeSlice` с `sync.Mutex`.\n2. Реализуем метод `Append(val int)`.\n3. Запустим 1000 горутин, выполняющих конкурентный `Append`.\n4. Проверим результат с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeSlice struct {\n\tmu   sync.Mutex\n\tdata []int\n}\n\nfunc (s *SafeSlice) Append(val int) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\ts.data = append(s.data, val)\n}\n\nfunc (s *SafeSlice) Len() int {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\treturn len(s.data)\n}\n\nfunc main() {\n\tsafe := &SafeSlice{}\n\tvar wg sync.WaitGroup\n\tconst total = 1000\n\n\twg.Add(total)\n\tfor i := 0; i < total; i++ {\n\t\tgo func(val int) {\n\t\t\tdefer wg.Done()\n\t\t\tsafe.Append(val)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Финальный размер среза: %d (Ожидалось: %d, Race отсутствует!)\\n", \n\t\tsafe.Len(), total)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Финальный размер среза: 1000 (Ожидалось: 1000, Race отсутствует!)'}], 'under_the_hood': 'Мьютекс гарантирует, что реаллокация подлежащего массива при росте `cap` среза происходит строго атомарно для одной горутины.', 'pitfalls': 'Без мьютекса параллельный `append` потеряет до 50% данных и выдаст ошибку `DATA RACE` в Race Detector.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему append в слайс не является потокобезопасным в Go?»\n**Ответ:** Потому что структура `reflect.SliceHeader` занимает 24 байта (3 машинных слова). Модификация `len`, `cap` и копирование указателя на массив `Data` не могут быть выполнены одной неделимой инструкцией CPU.'}, {'num': 41, 'title': 'Паттерн errgroup: конкурентный запуск N задач с отменой по первой ошибке', 'task': 'Реализуй **"errgroup"** вручную (или используй `golang.org/x/sync/errgroup`): запускаешь N горутин, если **любая** возвращает ошибку — отменяешь остальные через `context.WithCancel`. Собери первую ошибку.', 'theory': 'Паттерн `errgroup.Group`:\n1. Управление пулом горутин с `sync.WaitGroup`.\n2. Захват первой встреченной ошибки через `sync.Once`.\n3. Автоматическая отмена контекста `cancel()` для всех остальных параллельных задач.', 'step_by_step': '1. Реализуем структуру `CustomErrGroup` с `context.WithCancel` и `sync.Once`.\n2. Метод `Go(fn func() error)`.\n3. Метод `Wait() error`.\n4. Запустим 3 задачи, одна из которых сымитирует сбой.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype CustomErrGroup struct {\n\tctx      context.Context\n\tcancel   context.CancelFunc\n\twg       sync.WaitGroup\n\terrOnce  sync.Once\n\tfirstErr error\n}\n\nfunc WithContext(parent context.Context) (*CustomErrGroup, context.Context) {\n\tctx, cancel := context.WithCancel(parent)\n\treturn &CustomErrGroup{ctx: ctx, cancel: cancel}, ctx\n}\n\nfunc (g *CustomErrGroup) Go(fn func() error) {\n\tg.wg.Add(1)\n\tgo func() {\n\t\tdefer g.wg.Done()\n\t\tif err := fn(); err != nil {\n\t\t\tg.errOnce.Do(func() {\n\t\t\t\tg.firstErr = err\n\t\t\t\tg.cancel() // Отменяем все остальные горутины при первой ошибке!\n\t\t\t})\n\t\t}\n\t}()\n}\n\nfunc (g *CustomErrGroup) Wait() error {\n\tg.wg.Wait()\n\tg.cancel()\n\treturn g.firstErr\n}\n\nfunc main() {\n\tg, ctx := WithContext(context.Background())\n\n\t// Задача 1: Успешная\n\tg.Go(func() error {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\treturn nil\n\t})\n\n\t// Задача 2: Завершается с ошибкой\n\tg.Go(func() error {\n\t\ttime.Sleep(15 * time.Millisecond)\n\t\treturn errors.New("ошибка базы данных: connection refused")\n\t})\n\n\t// Задача 3: Долгая (должна быть отменена)\n\tg.Go(func() error {\n\t\tselect {\n\t\tcase <-time.After(100 * time.Millisecond):\n\t\t\treturn nil\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Println(" -> [Task #3] Успешно прервана по сигналу отмены!")\n\t\t\treturn ctx.Err()\n\t\t}\n\t})\n\n\terr := g.Wait()\n\tfmt.Printf("[Main] Итоговая ошибка errgroup: %v\\n", err)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> [Task #3] Успешно прервана по сигналу отмены!\n# [Main] Итоговая ошибка errgroup: ошибка базы данных: connection refused'}], 'under_the_hood': '`sync.Once` гарантирует, что переменная `firstErr` сохранит строго первую произошедшую ошибку.', 'pitfalls': 'Все задачи внутри `errgroup` обязаны слушать `ctx.Done()`, чтобы отмена действительно останавливала выполнение.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы ключевые методы пакета golang.org/x/sync/errgroup?»\n**Ответ:** `g, ctx := errgroup.WithContext(ctx)` создает группу, метод `g.Go(fn)` запускает задачу, `g.SetLimit(N)` ограничивает параллелизм (в Go 1.20+), а `g.Wait()` блокируется до завершения всех задач и возвращает первую ошибку.'}, {'num': 42, 'title': 'Слияние двух независимых каналов: функция Merge(ch1, ch2)', 'task': '**Fan-in (Слияние)**: Напиши функцию `Merge(ch1, ch2 <-chan int) <-chan int`. Внутри запусти горутину, которая читает из обоих каналов (через `select` или горутины с WaitGroup) и пишет данные в один общий выходной канал.', 'theory': 'Бинарный Fan-In для слияния двух каналов с гарантией закрытия выхода после исчерпания обоих источников.', 'step_by_step': '1. Объявим `Merge(ch1, ch2 <-chan int) <-chan int`.\n2. Запустим 2 горутины с `sync.WaitGroup`.\n3. В фоновой горутине вызовем `close(out)`.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc Merge(ch1, ch2 <-chan int) <-chan int {\n\tout := make(chan int)\n\tvar wg sync.WaitGroup\n\n\tforward := func(c <-chan int) {\n\t\tdefer wg.Done()\n\t\tfor val := range c {\n\t\t\tout <- val\n\t\t}\n\t}\n\n\twg.Add(2)\n\tgo forward(ch1)\n\tgo forward(ch2)\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(out)\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tc1 := make(chan int, 2)\n\tc2 := make(chan int, 2)\n\n\tc1 <- 10; c1 <- 20; close(c1)\n\tc2 <- 30; c2 <- 40; close(c2)\n\n\tmerged := Merge(c1, c2)\n\n\tfor res := range merged {\n\t\tfmt.Printf("Получено значение: %d\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено значение: 10\n# Получено значение: 20\n# Получено значение: 30\n# Получено значение: 40'}], 'under_the_hood': 'Две горутины `forward` безопасно пишут в общий `out`.', 'pitfalls': 'Не закрывайте `out` до завершения обеих горутин.', 'bigtech_interview': '**Вопрос с собеседования:** «Можно ли сделать Merge(ch1, ch2) без создания двух горутин?»\n**Ответ:** Можно через одну горутину с циклом `for ch1 != nil || ch2 != nil` и `select`, выставляя закрытый канал в `nil` (`ch = nil`).'}, {'num': 43, 'title': 'Ограничение частоты запросов (Rate Limiting) с time.NewTicker (5 RPS)', 'task': '**Ограничение частоты запросов (Rate Limiting)**: Напишите программу, имитирующую отправку запросов к внешнему API. API разрешает обрабатывать не более 5 запросов в секунду. Используйте тикер `time.NewTicker`, чтобы ограничить частоту отправки запросов (ровно 1 запрос каждые 200 миллисекунд).', 'theory': 'Периодический тикер `time.NewTicker(200 * time.Millisecond)` обеспечивает жесткий лимит 5 запросов в секунду (5 RPS).', 'step_by_step': '1. Создадим тикер `ticker := time.NewTicker(20 * time.Millisecond)`.\n2. Обязательно вызовем `defer ticker.Stop()`.\n3. В цикле будем считывать `<-ticker.C` перед каждым сетевым запросом.\n4. Выведем точные таймштампы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\t// Лимит: 1 запрос каждые 20 мс (эмуляция 50 RPS для быстрого теста)\n\trateTicker := time.NewTicker(20 * time.Millisecond)\n\tdefer rateTicker.Stop()\n\n\trequests := []int{101, 102, 103, 104}\n\tstart := time.Now()\n\n\tfor _, reqID := range requests {\n\t\t<-rateTicker.C // Ожидание тика перед отправкой\n\t\tfmt.Printf("[API Client] Отправлен запрос #%d в %v\\n", \n\t\t\treqID, time.Since(start).Round(time.Millisecond))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [API Client] Отправлен запрос #101 в 20ms\n# [API Client] Отправлен запрос #102 в 40ms\n# [API Client] Отправлен запрос #103 в 60ms\n# [API Client] Отправлен запрос #104 в 80ms'}], 'under_the_hood': '`ticker.C` выдает временную метку каждые $N$ миллисекунд.', 'pitfalls': 'Всегда вызывайте `ticker.Stop()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы ограничения простого rate limiting на time.NewTicker?»\n**Ответ:** Простой тикер не разрешает кратковременные всплески трафика (bursts). Для поддержки всплесков используют библиотеку `golang.org/x/time/rate`.'}, {'num': 44, 'title': 'Безопасное закрытие каналов через sync.Once (Safe Channel Close)', 'task': 'Закрытие закрытого канала: продемонстрируйте панику. Исправьте, используя флаг или `sync.Once` для безопасного закрытия.', 'theory': 'Повторный вызов `close(ch)` на уже закрытом канале немедленно вызывает фатальную панику `panic: close of closed channel`. Паттерн `SafeClose` на базе `sync.Once` гарантирует, что канал закроется строго один раз даже при сотнях параллельных вызовов `Close()`.', 'step_by_step': '1. Создадим структуру `SafeChannel` с `sync.Once`.\n2. Реализуем метод `Close()`.\n3. Запустим 10 горутин, одновременно вызывающих `Close()`.\n4. Убедимся в отсутствии паники.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeChannel[T any] struct {\n\tCh   chan T\n\tonce sync.Once\n}\n\nfunc NewSafeChannel[T any](size int) *SafeChannel[T] {\n\treturn &SafeChannel[T]{\n\t\tCh: make(chan T, size),\n\t}\n}\n\nfunc (sc *SafeChannel[T]) SafeClose() {\n\tsc.once.Do(func() {\n\t\tclose(sc.Ch)\n\t\tfmt.Println("[SafeChannel] Канал безопасно закрыт ровно один раз.")\n\t})\n}\n\nfunc main() {\n\tsc := NewSafeChannel[int](10)\n\tvar wg sync.WaitGroup\n\n\t// 5 параллельных горутин пытаются одновременно закрыть один канал\n\tfor i := 1; i <= 5; i++ {\n\t\twg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tsc.SafeClose()\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Программа завершена без паники \'close of closed channel\'!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run -race main.go\n# Вывод:\n# [SafeChannel] Канал безопасно закрыт ровно один раз.\n# [Main] Программа завершена без паники 'close of closed channel'!"}], 'under_the_hood': '`sync.Once` использует быстрый атомарный путь `atomic.LoadUint32` и мьютекс для первого выполнения.', 'pitfalls': 'Никогда не используйте `recover()` для маскировки повторного закрытия каналов — используйте `sync.Once`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go нет встроенной функции bool isClosed(ch)?»\n**Ответ:** Потому что к моменту, когда `isClosed(ch)` вернула бы `false`, другая горутина уже успела бы вызвать `close(ch)`, сделав результат проверки неактуальным (Time-of-Check to Time-of-Use bug).'}]
